    "yasaStory": "1651년 1월 1일 사건: 찰스 2세가 스코틀랜드 왕위에 올랐다.\n\n찰스 2세(Charles II, 1630년 5월 29일~1685년 2월 6일)는 잉글랜드, 아일랜드 및 스코틀랜드의 군주이다. 1649년 아버지인 찰스 1세가 잉글랜드 의회의 재판에 의해 처형된 뒤 왕위 계승을 선언하였으나 공화제를 선포한 잉글랜드 연방이 운영되는 동안 망명 생활을 했고 1660년 왕정복고 이후에야 실질적인 군주로서 재위할 수 있었다. 찰스 1세와 앙리에트 마리 드 프랑스 사이의 차남으로, 원래 위에 형이 한 명 있었지만 태어나고 하루 만에 요절했기 때문에 사실상 둘째였던 그가 장남으로 올라가면서 1649년 1월 30일, 아버지 찰스 1세가 처형된 직후인 2월 5일 스코틀랜드 의회에 의해 잉글랜드 왕세자에서 스코틀랜드 국왕으로 선포되었다. 그러나 당시 잉글랜드는 호국경이 정부를 대표하는 공위시대를 이어갔기 때문에 당시 찰스 2세의 잉글랜드 및 아일랜드에 대한 군주 권한 선포는 상징적 주장에 불과하였다. 1651년 9월 3일 우스터 전투를 끝으로 잉글랜드 내전이 청교도를..."
