    "yasaStory": "1956년 1월 1일 사건: 수단과 이집트가 영국으로부터 독립하였다.\n\n수단 공화국(아랍어: جمهورية السودان 줌후리야트 앗수단[*], 영어: Republic of the Sudan 리퍼블릭 오브 더 수단[*]), 약칭 수단은 아프리카 북부에 있는 나라이다. 국호인 수단은 아랍어 표현인 빌라드 앗수단(بلاد السودان →흑인들의 땅, bilād as-sūdān)에서 유래한다. 2023년 기준으로 세계에서 15번째로 넓다. 북쪽에 이집트, 북동쪽에 홍해, 동쪽에 에리트레아와 에티오피아, 남서쪽에 중앙아프리카 공화국, 남쪽에 남수단, 서쪽에 차드와 북서쪽에 리비아를 접경하고 있다. 세계에서 가장 긴 강인 나일강이 수단을 동쪽과 서쪽으로 가르며 흐른다."
