    "yasaStory": "1984년 1월 1일 사건: 브루나이가 영국으로부터 독립하였다.\n\n브루나이 다루살람(말레이어: Negara Brunei Darussalam 느가라 브루나이 다루살람[*], 문화어: 브루네이 다루쌀람), 줄여서 브루나이(말레이어: Brunei, 문화어: 브루네이)는 동남아시아 보르네오섬의 북서 연안에 있는 술탄국이다. 남중국해와 맞닿아 있는 해안을 제외하고는 말레이시아 사라왁주에 둘러싸여 있고, 사라왁주의 림방에 의해 두 지역으로 나뉘어 있다. 브루나이는 보르네오섬에만 영토가 있는 유일한 국가이며, 섬의 나머지 부분은 말레이시아와 인도네시아에 속해 있다. 인구는 대략 45만 명이다 (2023년). 브루나이는 인간 개발 지수가 동남아시아에서 싱가포르에 이어 두 번째로 높고, 국제통화기금이 선정한 구매력 평가 기준 1인당 GDP가 세계에서 4번째로 높은 국가이다. 이 나라는 ASEAN, APEC, 영연방 등에 속해 있으며 수도는 반다르스리브가완이다."
