    "yasaStory": "1863년 1월 10일 사건: 세계 최초의 지하철이 영국 런던에서 운행 시작.\n\n지하철(地下鐵, 영어: metro, underground, subway, tube) 또는 지하철도(地下鐵道)는 도시철도의 가장 대표적 형태로, 노선 대부분이 지표면 아래 터널에 부설되어 지상의 교통과 완전하게 분리된 전용 궤도를 사용하는 대량 운송 체계다. 외각 지역에서는 지상 노선도 있으나, 도심지에서는 노선이 주로 지하에 있는 도시 철도이다. 지하철은 일반적으로 도시 지역에 건설되는 고용량 대중교통의 한 유형이다. 버스나 트램과 달리 고속 교통 시스템은 보행자나 다른 차량이 접근할 수 없는 독점적인 통행 우선권으로 운행되는 철도(보통 전기)이다. 터널이나 고가 철도에서는 등급별로 구분되는 경우가 많다. 고속 운송 시스템에 대한 최신 서비스는 일반적으로 철도 선로에서 전기 다중 장치를 사용하여 역 간 지정된 노선에서 제공된다. 일부 시스템은 유도 고무 타이어, 자기 부상(자기 부상) 또는 모노레일을 사용한다. 역에는 일반적으로 열차 내부에 계단이 없는 높은 플랫폼이 있으므로 열차와..."
