    "yasaStory": "1983년 1월 17일 사건: 영국 BBC에서 아침 시간대 프로그램 〈브렉퍼스트 타임〉 첫 방송.\n\nBBC(영어: British Broadcasting Corporation, BBC)은 영국 런던의 공영 방송사이다. 영국방송공사(英國放送公社)로 불리기도 한다. 채널은 BBC1, BBC2, BBC3, BBC4, CBBC, Ceebeebies, BBC News, BBC Parliament, BBC World로 나뉘어 있다. BBC의 주력 방영 서비스 BBC One과 BBC Two, BBC 라디오 1, 2, 3, 4 그리고 5 라이브는 아날로그 주파수로 송신하며 나머지 채널들은 디지털로 송신한다. BBC Parliament는 영국의 유일한 정치 전문 채널이다. 시사 프로그램을 텔레비전과 라디오 그리고 인터넷을 통해 전 세계에 방영한다. BBC는 다큐멘터리로 유명하다. 과학, 역사, 사회, 물리, 지구과학, 고생물학을 주제로 한 수많은 다큐멘터리가 BBC에서 제작되었으며 다큐에서 제공하는 정보의 정확성과 풍부한 장르 및 영상들로 인해 현재 BBC 다큐는 수많은 시청자들의 인기를 누리고 있는..."
