    "yasaStory": "1902년 1월 30일 사건: 영일 동맹, 런던에서 체결.\n\n영일 동맹(日英同盟(Nichi-Ei Dōmei))은 영국과 일본 제국 사이의 동맹으로, 1902년부터 1923년까지 유지되었다. 동맹을 수립한 조약은 1902년 1월 30일 런던의 랜즈다운 하우스에서 영국의 외무장관 랜즈다운 경과 일본의 외교관 하야시 다다스에 의해 서명되었다. 일본을 포함한 아시아 국가들에게 강요되었던 이전의 불평등 조약 시대를 거쳐, 이 동맹은 서구 열강과 비서구 국가 사이에 보다 대등한 조건으로 체결된 군사 협정이었다. 이는 일본의 경제, 사회, 군사를 현대화하고 산업화한 메이지 시대 개혁의 성공을 반영한 것이었으며, 이를 통해 일본은 다른 아시아 국가들과 공유했던 열등한 지위에서 벗어날 수 있었다. 이 협정의 공동 동기 중 하나는 외교적 동맹이 아시아에서 영국과 일본의 제국주의적 이익을 침해할 수 있는 다른 세계 열강들을 저지할 수 있다는 점이었다. 영국에게 이 동맹은 \"화려한 고립\" 시대의 종말을 의미했으며, 제국의 과도한 개입을 줄이고 영국 왕립 해군을 소환해..."
