    "yasaStory": "1547년 1월 28일 사건: 에드워드 6세, 잉글랜드 국왕으로 즉위하다.\n\n에드워드 6세(Edward VI, 1537년 10월 12일 - 1553년 7월 6일)는 튜더가의 잉글랜드 국왕이다. 당시 잉글랜드의 군주는 아일랜드의 국왕을 겸했기 때문에 에드워드 6세 역시 두 왕국의 군주로 재위하였다. 1537년 10월 12일 헨리 8세와 제인 시모어 사이에서 헨리 8세가 그토록 고대하던 아들로 태어났다. 에드워드 6세가 태어난 시기 잉글랜드 교회는 이미 수장령으로 로마 가톨릭교회에서 분리되어 있었기 때문에, 에드워드 6세는 태어나면서 부터 개신교도로서 자란 잉글랜드의 첫 군주였다. 1547년 2월 20일 아홉살의 나이로 즉위하여 재위 기간 동안 실제 통치는 섭정에 의해 이루어졌다. 초기 섭정은 외삼촌이었던 서머싯 공작가의 에드워드 시모어이었고 그가 동생 토머스 시모어과 권력 암투 끝에 몰락한 뒤로는 노섬벌랜드 공작 존 더들리가 섭정이 되었다. 에드워드 6세 시기의 잉글랜드는 밖으로는 오랜 숙적인 스코틀랜드와 여전히 전쟁이 있었고 안으로는 반란의 위기를 겪었다. 이러한..."
