    "yasaStory": "1534년 2월 11일 사건: 수장령(Acts of Supremacy, 首長令): 헨리 8세가 로마 교황청과의 관계를 단절하고 영국 교회에 대한 모든 권한이 국왕에게 있음을 선포하다.\n\n수장령 (Acts of Supremacy, 首長令) 또는 수장법은 1534년 영국 왕 헨리 8세가 로마 교황청과의 관계를 단절하고 영국 교회를 관리하는 모든 권한이 국왕에게 있음을 선포한 법령이다. 이 법에 따라 기독교 역사에서 성공회의 시초가 마련된다."
