    "yasaStory": "2000년 2월 11일 사건: 영국 정부, 북아일랜드 자치권 회수 및 직접 통치 개시(북아일랜드 분쟁)\n\n북아일랜드(아일랜드어: Tuaisceart Éireann 스코트어: Norlin Airlann)는 아일랜드섬의 북동쪽에 위치한 영국의 일부로서, 국가, 지방 또는 지역으로 다양하게 묘사된다. 북아일랜드는 남쪽과 서쪽으로 아일랜드 공화국과 개방된 국경을 공유한다. 2021년 기준 인구는 1,903,100명으로 영국 인구의 약 3%, 아일랜드 인구의 27%를 차지한다. 1998년 북아일랜드법에 의해 설립된 북아일랜드 의회가 다양한 위임된 정책 사항에 대한 책임을 지고 있으며, 그 외의 분야는 영국 정부에 유보되어 있다. 북아일랜드 정부는 벨파스트 협정에 따라 여러 영역에서 아일랜드 정부와 협력한다. 아일랜드 공화국은 영국-아일랜드 정부 회의(BIIG)를 통해 위임되지 않은 정부 문제에 대한 협의 역할도 가지고 있다. 북아일랜드는 1920년 아일랜드 정부법에 의해 아일랜드가 분할되었을 때인 1921년에 만들어졌고, 6개의 북동쪽 주들에 대해 위임된 정부를 만들었다. 웨스트민스터의 조합원들과..."
