    "yasaStory": "2012년 2월 12일 사건: 영국 가수 아델이 제54회 그래미상에서 올해의 레코드상, 올해의 앨범을 포함해 6개 부문에서 상을 받다.\n\n아델 로리 블루 애드킨스(Adele Laurie Blue Adkins, MBE, 1988년 5월 5일 ~ )는 아델로 잘 알려져 있는 잉글랜드의 싱어송라이터, 배우이다. 2006년 친구가 마이스페이스에 올린 데모 영상이 계기가 돼 XL 레코딩스와 계약을 체결했다. 2008년 1월 발매한 데뷔 앨범 19는 평단의 긍정적인 평가와 함께 큰 상업적 성과를 거뒀다. 19는 영국에서 쿼드러플 플래티넘, 미국에서는 더블 플래티넘 인증을 받았다. 같은 해 BBC에 의해 《사운드 오브 2008》으로 선정됐고, 브릿 어워드에서는 첫 Critics' Choice에 선정됐다. 또한 2008년 말 미국 프로그램 《새터데이 나이트 라이브》에 출연한 계기로 미국에서 관심을 받기 시작했다. 그리고 2009년 열린 그래미 상에서는 최우수 신인상과 최우수 여성 팝 보컬 퍼포먼스상을 수상했다. 2011년 초에는 두 번째 정규 앨범 21이 발매되었다. 전 세계적으로 엄청난 상업적 성과를 거뒀다. 2012 그래미상에서..."
