    "yasaStory": "1951년 2월 18일 사건: 네팔, 영국으로부터 독립.\n\n네팔 연방민주공화국(네팔어: सङ्घीय लोकतान्त्रीक गणतन्त्र नेपाल 산기야 로크탄트리크 가나탄트라 네팔, 문화어: 네팔 련방 민주주의 공화국), 약칭 네팔(네팔어: नेपाल 네팔, 영어: Nepal)은 남아시아 히말라야에 위치한 나라로, 중국과 인도에 둘러싸여 있으며 동쪽 조금 멀리 떨어진 곳에 부탄이 있다. 2007년 1월 15일에 왕정이 종식되고 과도 정부로 정치 체제가 변경되었으며, 2008년 5월 28일에 네팔 연방민주공화국이 수립되었다. 2022년 기준으로 세계에서 가장 최근에 세워진 민주 공화국이다. 147,516km2의 영역과 29,187,037명(2022년 기준)의 인구를 가진 네팔은 세계에서 93번째로 넓은 나라이고, 41번째로 인구가 많은 나라이다. 네팔의 수도인 카트만두는 네팔에서 가장 큰 대도시로, 다양하고 풍부한 지리적, 종교적, 문화적 배경을 가지고 있다. 북부 산악지대는 에베레스트 산을 포함하여 세계에서 가장 큰 10대 산 중 8개가..."
