    "yasaStory": "1965년 2월 18일 사건: 감비아, 영국으로부터 독립.\n\n감비아(영어: The Gambia), 공식 국명 감비아 공화국(영어: Republic of The Gambia)은 아프리카 서해안에 있는 국가이다. 대서양에 접한 감비아강의 하구를 제외하고는, 세네갈에 둘러싸여 있다. 수도는 반줄이다. 1965년 2월 18일 영연방의 자치령으로서 독립했다. 주민은 세네갈과 동일한 흑인이며 대부분이 회교도이며 공용어는 영어이다. 주요 산물인 땅콩이 재배되어 수출고의 93%를 차지한다. 그 밖에 야자열매·모피 등이 생산되고 어업이 성하며 지하자원은 보크사이트 등이 있다. 주요 도시로는 반줄, 세레쿤다, 바세산타수, 반상, 파라페니 등이 있다."
