    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%A1%B4_%EC%BA%90%EB%B2%97",
    "officialRecord": "존 캐벗이 잉글랜드 헨리 7세로부터 북서항로 개척을 위한 특허장 발부받음.진 프리츠 푸른숲 2003 p111",
    "yasaStory": "1496년 3월 5일 사건: 존 캐벗이 잉글랜드 헨리 7세로부터 북서항로 개척을 위한 특허장 발부받음.진 프리츠 푸른숲 2003 p111\n\n존 캐벗(영어: John Cabot, 이탈리아어: Giovanni Caboto 조반니 카보토[*]), 1450년? ~ 1499년 8월 14일?)은 이탈리아 출신 잉글랜드의 항해가·탐험가로, 바이킹들의 방문이래 북아메리카 대륙을 발견한 첫 유럽인으로 인정받고 있다. 잉글랜드 헨리 7세의 후원하에 1497년에 진행된 그의 탐험으로 뉴펀들랜드를 발견했으며, 이것이 기초가 되어 영국이 캐나다를 식민지화 할 수 있는 근거가 되었다. 영국의 아메리카 대륙 개척사에 있어서 선구자라고 할 수 있다. 존 캐벗의 탐험 이후 영국은 프랑스와 북미 캐나다 지역에서 식민지 확보 경쟁을 벌였고, 18세기 후반에 발생한 프렌치 인디언 전쟁에서 승리하면서 캐나다의 영유권을 차지하였다."
