    "yasaStory": "1946년 3월 5일 사건: 윈스턴 처칠이 미국 미주리주 웨스트민스터 대학교의 연설에서 “철의 장막”이라는 말을 처음 사용함.\n\n더 라이트 아너러블 윈스턴 레너드 스펜서 처칠 경 KG OM CH TD DL FRS RA(영어: The Right Honourable Sir Winston Leonard Spencer Churchill KG OM CH TD DL FRS RA, 1874년 11월 30일~1965년 1월 24일)은 영국의 정치인, 군인, 작가로 제2차 세계 대전 도중인 1940년부터 1945년과 그 이후 1951년부터 1955년까지 영국의 총리를 지냈다. 1900년부터 1964년 사이 62년 동안 하원의원(MP)이었으며 이 동안 총 5개의 선거구를 대표했다. 경제적 자유주의와 제국주의를 고수했던 처칠은 정치 경력 대부분을 자신이 1940년부터 1955년까지 이끌었던 보수당 소속으로 지냈으며, 1904년부터 1924년까지는 자유당 소속이었다. 처칠은 옥스퍼드셔주에서 귀족 가문 스펜서가에서 태어났다. 1895년 영국 육군에 입대하여 영국령 인도, 마흐디 전쟁, 제2차 보어 전쟁 등에서 전투를 치렀으며, 이후..."
