    "yasaStory": "1957년 3월 6일 사건: 가나 공화국이 영국령에서 독립하다.\n\n가나 공화국(영어: Republic of Ghana 리퍼블릭 오브 가나[*]), 약칭 가나(영어: Ghana)는 서아프리카 기니만과 대서양에 면한 나라다. 총 면적은 238,535 km2 (92,099 sq mi)로 동쪽으로는 토고, 서쪽으로는 코트디부아르, 북쪽으로는 부르키나파소와 맞닿아 있으며, 남쪽으로는 대서양과 기니만을 면하고 있다. 나라 이름은 소닝케어로 '전사왕'이라는 뜻이다. 수도는 아크라이다. 오늘날 가나 영토에 처음으로 나라가 세워진 때는 11세기로 거슬러 올라간다. 수 세기에 걸쳐서 많은 왕국과 제국들이 등장했으며, 아샨티 왕국이 가장 강력한 통일 국가를 세운 것으로 알려져 있다. 15세기 이후로 유럽 세력들이 서아프리카에서 무역을 장악하고자 다투었으며, 19세기 말에 대영 제국이 최종적으로 가나 지방의 해안을 접수했다. 원주민들의 저항이 있었지만 영국령 골드코스트가 세워지고 1900년대에 오늘날의 가나 영토가 확정됐다. 1957년 3월 6일에 영국으로부터 독립했다..."
