    "category": "episode",
    "interestScore": 90,
    "title": "이란이 샐먼 루시디의 소설 《악마의 시》 문제로 영국과 단교.",
    "source": "위키백과 · 이란",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%9D%B4%EB%9E%80",
    "officialRecord": "이란이 샐먼 루시디의 소설 《악마의 시》 문제로 영국과 단교.",
    "yasaStory": "1989년 3월 7일 사건: 이란이 샐먼 루시디의 소설 《악마의 시》 문제로 영국과 단교.\n\n이란 이슬람 공화국(페르시아어: .جمهوری اسلامی ایران 좀후리예 에슬라미예 이란, 영어: Islamic Republic of Iran, IRI), 줄여서 이란 이슬람 공화국(페르시아어: ایران)은 서아시아의 이슬람 공화국이다. 북서쪽으로 아르메니아와 아제르바이잔과 접경하고, 북쪽으로는 카스피해가 있으며 북동쪽에는 투르크메니스탄, 동쪽으로는 아프가니스탄이 있다. 남동쪽에는 파키스탄이 자리하며, 남부 해안선을 따라 페르시아만과 오만만이 있으며 서쪽으로는 튀르키예, 이라크와 접경한다. 이란의 국토 면적은 1,648,195km2이며, 인구는 약 9,300만 명 정도이다. 서아시아에서는 2번째로 거대한 국가이자 아시아의 중동국가 중에서는 인구가 가장 많다. 수도이자 최대 도시는 테헤란이다. 이란은 세계에서 가장 오래된 문명들의 발상지이다. 기원전 4000년 경 엘람의 왕국들이 일어나기 시작하였다. 기원전 700년경에 이란계 메디아인들이 이란 유역을 통합하는 데에 성공하였다...."
