    "yasaStory": "1926년 3월 7일 사건: 뉴욕과 런던 간 첫 대서양 횡단 무선전화 교신 성공.\n\n뉴욕(영어: New York) 또는 뉴욕시(영어: New York City 뉴욕 시티[*], 영어: City of New York 시티 오브 뉴욕[*], 영어: NYC)는 미국의 북동부, 뉴욕주의 남쪽 끝에 있는 도시이자 미국에서 가장 인구가 많은 도시이자 전 세계에서 가장 인구가 많은 도시 중 하나이자 미국의 최대 도시이다. 세계적인 대도시인 뉴욕은 상업, 금융, 미디어, 예술, 패션, 연구, 기술, 교육, 엔터테인먼트 등 많은 분야에 걸쳐 큰 영향을 끼치고 있으며, 도쿄, 런던과 함께 세계적인 글로벌 도시이자 세계의 문화 수도로 불리기도 한다. 이 외에도 뉴욕은 국제 외교에서 중요한 도시이며, 유엔 본부가 있다. 뉴욕항은 세계에서 가장 큰 자연 항구 가운데 하나이다. 뉴욕은 맨해튼, 브루클린, 퀸스, 브롱크스, 스태튼아일랜드와 같은 다섯 개의 자치-독립구로 나뉘어 있다. 이 자치구들은 각각 독립되어 있었다가 1898년 뉴욕에 합병되었다. 뉴욕의 인구는 2011년을 기준으로 8,244..."
