    "yasaStory": "1905년 3월 10일 사건: 영국의 축구 클럽 첼시 FC 창단.\n\n축구(蹴球, 영어: association football or football 또는 soccer)는 11명의 선수들이 각각 한 팀을 이루어 주로 발을 사용하여 골대에 공을 넣는 구기 단체 스포츠, 현재 세계적으로 가장 인기있는 스포츠이다. 경기장은 직사각형이며, 바닥은 천연잔디나 인조잔디 등으로 이루어져 있다. 경기장 양 끝에 놓인 상대방 골대 안으로 공을 통과시키면 득점이 된다. 선수 중 골키퍼만 팔과 손으로도 공을 건드릴 수 있으나, 팔과 손을 사용할 수 있는 구역이 제한되어 있다. 나머지 선수들은 팔과 손을 제외한 신체 부위로만 공을 다룰 수 있다. 골키퍼 외의 선수가 경기장 안에서 팔이나 손으로 공을 고의로 다루면 핸드볼 반칙 이 된다. 주로 발을 사용하여 공을 차며, 공이 공중에 떠있을 때에는 몸과 머리를 이용하는 것이 보통이다. 경기 종료 시점까지 더 많은 득점을 올린 팀이 승리하며, 동점일 때는 대회 규칙에 따라 무승부로 처리하거나 연장전과 승부차기로 승패를 결정 짓는다..."
