    "yasaStory": "1306년 3월 25일 사건: 로버트 1세가 스코틀랜드의 왕위에 오르다.\n\n로버트 1세 브루스(중세 아일랜드어: Roibert I a Briuis, 스코틀랜드 게일어: Raibeart I Bruis, 영어: Robert I Bruce, 라틴어: Robertus Brussius, 1274년 7월 11일 ~ 1329년 6월 7일)는 스코트인의 왕으로 1306년 왕위에 올라 23년간의 재위기간 동안 스코틀랜드 왕국을 다스렸다. 스코틀랜드 독립의 열렬한 지도자이자 윌리엄 월리스의 동시대로 알려지면서 스코틀랜드의 가장 사랑 받은 국민적 영웅들 중의 하나로 남아있는 로버트 1세는 14세기 초 제1차 스코틀랜드 독립 전쟁을 이끌었으며, 1314년 6월 23일 배넉번 전투를 지휘하여 에드워드 2세가 이끄는 잉글랜드군의 침공을 막아 내었다. 현재 스코틀랜드의 사실상 국가인 스코틀랜드의 꽃의 가사는 이 배넉번 전투를 다루고 있다."
