    "officialRecord": "아르헨티나가 포클랜드 제도의 영국 군을 공격하면서 포클랜드 전쟁이 시작되다.",
    "yasaStory": "1982년 4월 2일 사건: 아르헨티나가 포클랜드 제도의 영국 군을 공격하면서 포클랜드 전쟁이 시작되다.\n\n아르헨티나 공화국(스페인어: República Argentina 레푸블리카 아르헨티나[*], 과라니어: Tetã Argentina) 줄여서 아르헨티나(스페인어: Argentina 아르헨티나[*], 문화어: 아르헨띠나)는 남아메리카 대륙 남부에 자리 잡고 있는 연방 공화국이다. 연방국가로서 23개의 주와 자치시 1개로 구성되어 있으며, 주요 도시로는 부에노스아이레스, 코르도바, 바이아블랑카, 마르델플라타, 라플라타 등이 있고 수도는 부에노스아이레스시이다. 동쪽의 대서양과 서쪽의 안데스산맥 사이에 2,766,890km2의 면적을 차지하여 남아메리카에서 브라질에 이어 두 번째로 넓으며, 세계에서 여덟 번째로 큰 나라이다. 아르헨티나는 북쪽으로는 파라과이와 볼리비아, 북동쪽으로는 브라질과 우루과이, 서·남쪽으로는 칠레와 국경을 싸우고 있다. 공용어는 스페인어이며 여러 차례의 대량 이민으로 이탈리아계 등 백인 인구가 대다수를 차지하고 있다. 아르헨티나는 또한 영국의 해외 영토로 인정되고 있는..."
