    "yasaStory": "2008년 4월 3일 사건: 2007년 강화 총기 탈취 사건의 조영국 피고인에게 1심 군사법원이 사형을 선고했다.\n\n강화 총기 탈취 사건(江華銃器奪取事件)은 2007년 12월 6일 대한민국 인천광역시 강화군에서 조영국(피의자, 사건 당시 35세)이 경계근무를 마치고 귀대 중인 해병대원의 총기를 탈취한 후 박영철 상병(피해자, 사건 당시 20세)을 흉기로 살해하고 이재혁 병장(사건 당시 20세)에게 중상을 입힌 사건이다."
