    "officialRecord": "'현대 서커스의 아버지' 필립 애스틀리(Philip Astley)가 영국 런던에 승마 학교를 열면서 현대적 서커스가 첫선을 보이다.",
    "yasaStory": "1768년 4월 4일 사건: '현대 서커스의 아버지' 필립 애스틀리(Philip Astley)가 영국 런던에 승마 학교를 열면서 현대적 서커스가 첫선을 보이다.\n\n서커스(circus)은 광대, 곡예사, 훈련된 동물, 공중그네 묘기, 음악가, 무용가, 후프 공연자, 줄타기 공연자, 저글링 공연자, 마술사, 복화술사, 외발자전거 공연자뿐만 아니라 다른 물체 조작 및 스턴트 지향 예술가 등 다양한 엔터테인먼트 쇼를 선보이는 공연자 집단이다. 곡마단(曲馬團) 또는 곡예단(曲藝團, 문화어: 교예단)이라고도 한다. \"서커스\"라는 용어는 또한 250년간의 현대 역사 동안 다양한 형식을 따라온 공연, 훈련 및 공동체의 분야를 나타내기도 한다. 비록 이 매체의 발명가는 아니지만, 뉴캐슬 언더 라임에서 태어난 필립 애슬리는 현대 서커스의 아버지로 불린다. 1768년, 숙련된 승마인 애슬리는 영국 템스강 남쪽의 하페니 해치라는 탁 트인 들판에서 승마 묘기 전시 공연을 시작했다. 1770년, 그는 승마 시연 사이의 공백을 메우기 위해 곡예사, 줄타기 공연자, 저글링 공연자, 광대를 고용했고, 이로써 나중에 \"서커스\"라고 명명된 형식을 우연히 발견했다. 다음 50년..."
