    "title": "영국에서 설탕법이 통과되다.",
    "source": "위키백과 · 설탕법",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%84%A4%ED%83%95%EB%B2%95",
    "officialRecord": "영국에서 설탕법이 통과되다.",
    "yasaStory": "1764년 4월 5일 사건: 영국에서 설탕법이 통과되다.\n\n설탕법(영어: Sugar Act)은 1764년 4월 5일, 영국 총리 조지 그렌빌의 주도로 영국 의회에서 제정한 관세에 관한 법률이다. 〈미국 수입법〉(American Revenue Act ), 〈미국 관세법〉(American Duties Act) 등으로도 불린다. 법의 서문에는 “이 왕국의 수익을 개선하기 위해 새로운 규정과 규제를 해야 한다 ... 또한 ... 수익을 높이기 위해 노력은 정당하고 필요하다 ... 위 물건을 방어하고, 보호하고, 안전을 확보하는 비용을 부담하기 위해”라고 쓰여 있다. 설탕법 제정 이전에는 〈당밀법〉(1733년 제정)이 있었으며, 이는 영국령 아닌 식민지에서 수입하는 당밀 1갤런 당 6펜스를 부과해서 영국령 서인도 제도산 당밀을 보호하기 위한 것이었지만, 식민지의 과세 회피로 실제로 징수되는 세금은 없었다. 설탕법은 관세율을 1갤런 당 3펜스를 감액하는 한편, 부과금의 강제력을 강화시킨 것이다. 또한 과세 대상도 와인, 커피, 의류 등으로 확대되었다...."
