    "yasaStory": "1955년 4월 5일 사건: 영국 수상 윈스턴 처칠이 건강 악화를 이유로 수상직에서 물러났다.\n\n그레이트브리튼 및 북아일랜드 연합왕국 총리(영어: Prime Minister of the United Kingdom of Great Britain and Northern Ireland), 줄여서 영국의 총리는 영국의 정부 수장이다. 2024년 7월 5일 노동당의 키어 스타머 후보가 영국의 제 80대 총리로 지휘봉을 잡았는데, 이는 74대 고든 브라운 이후 14년 만이다(총리는 영국 내각 의전서열 1위로, 중대국무공직에 해당). 총리하고 정부 내 모든 최고 부처의 수장들로 이루어진 내각은 국왕과 의회, 정당, 최종적으로는 유권자들에게 자신들의 정책과 행동에 대한 공동 책임이 있다. 영국 총리와 내각의 힘은 성문헌법에 명시되어 있지 않고 전통적으로 내려온 관습과 여러 보조적인 법률 제정의 결과로써 성립한다. 실질적으로는 영국 하원의 제1당 대표가 총리직을 수행하게 된다. 공식적으로 총리는 제1대장경과 국가공무원장관이라는 직책을 겸한다. 오늘날의 영국 총리의 권한은 법에 의해 제한받기도 하나..."
