    "officialRecord": "탕가니카공화국의 초대 대통령 줄리어스 니에레레가 영국군에 감사장을 수여했다.",
    "yasaStory": "1964년 4월 5일 사건: 탕가니카공화국의 초대 대통령 줄리어스 니에레레가 영국군에 감사장을 수여했다.\n\n탕가니카(Tanganyika)는 1961년부터 1964년까지 존재한 현재 탄자니아의 본토 부분을 구성하는 주권국이다. 1961년 12월 9일 영국으로부터 엘리자베스 2세 여왕을 군주로 하는 영연방 왕국으로 독립하였고 1년 후 영연방 내의 공화국이 되었다. 1964년 4월 22일 연합 규약에 서명하고 4월 25일 연합법을 통과시킨 후, 탕가니카는 1964년 4월 26일 연합날에 공식적으로 잔지바르 인민공화국과 통합하여 탕가니카-잔지바르 연합공화국을 형성했다. 새로운 국가는 1년 이내에 국명을 탄자니아 연합공화국으로 변경했다."
