    "title": "오스카 와일드가 런던에서 동성연애 혐의로 체포되다.",
    "source": "위키백과 · 오스카 와일드",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%98%A4%EC%8A%A4%EC%B9%B4_%EC%99%80%EC%9D%BC%EB%93%9C",
    "officialRecord": "오스카 와일드가 런던에서 동성연애 혐의로 체포되다.",
    "yasaStory": "1895년 4월 6일 사건: 오스카 와일드가 런던에서 동성연애 혐의로 체포되다.\n\n오스카 핑걸 오플래허티 윌스 와일드(영어: Oscar Fingal O'Flahertie Wills Wilde, 1854년 10월 16일 ~ 1900년 11월 30일)는 아일랜드의 시인, 소설가, 극작가이다. 1880년대에 걸쳐 여러 다른 형식으로 글을 썼으며, 이후 1890년대 초 런던의 가장 유명한 극작가 가운데 하나가 되었다. 와일드는 경구와 희곡, 그리고 유일한 장편소설 《도리언 그레이의 초상》으로 가장 유명하다. 와일드는 퀸즈베리 사건이라는 유명한 재판으로 인해 극적인 몰락을 겪게 되고, '막중한 풍기문란'으로 감옥에 수감된다. 학자인 H. 몽고메리 하이드는 이 용어가 영국 법정에서 비역죄에까지 이르지 않은 동성애를 의미한다고 주장한다. 그는 이 사건 때문에 영국에서 영원히 추방되어 평생 돌아가지 못했으며 1900년 프랑스 파리에서 뇌수막염에 걸려 사망했다."
