    "officialRecord": "마틸다 황후가 잉글랜드의 레이디(Lady of the English)로 선출됨으로써 영국 최초의 여성 통치자가 되다.",
    "yasaStory": "1141년 4월 7일 사건: 마틸다 황후가 잉글랜드의 레이디(Lady of the English)로 선출됨으로써 영국 최초의 여성 통치자가 되다.\n\n마틸다 (Matilda, 1102년 2월 7일- 1167년 9월 10일)는 잉글랜드 최초의 여성 통치자로 잉글랜드의 왕 헨리 1세와 스코틀랜드의 마틸다와의 사이에 장녀로 태어났다. 같은 이름을 가진 많은 역사상의 인물과 구별하기 위해 모드 황후(Empress Maud) 등으로 불린다. 신성로마제국의 황제 하인리히 5세와 결혼했으나 23살이 되던 해인 1125년에 하인리히 5세가 사망하여 미망인이 되었다. 둘 사이에 아이가 없었기 때문에 독일 잘리어 왕조는 단절되었다. 마틸다는 귀국한 후에 1128년에 앙주의 조프루아와 재혼하였다. 부친 헨리 1세에 의해 왕위계승자가 되었으나 1135년에 헨리 1세가 사망한 후 사촌인 스티븐에게 권력을 찬탈당했다. 왕위계승전을 통해 승기를 잡았으나 여왕에 대한 귀족들의 반발과 외국인과 결혼했다는 점 때문에 런던시민들에게 거부당하여 권력을 잡지는 못했다. 마틸다가 비록 잉글랜드의 첫 여성 군주이긴 하지만, 실질적인 지배자로서 잉글랜드에 군림한 기간이 1141년의..."
