    "title": "그레이트브리튼 아일랜드 연합왕국에서 최초의 우표인 페니 블랙을 발행하다.",
    "source": "위키백과 · 그레이트브리튼 아일랜드 연합왕국",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EA%B7%B8%EB%A0%88%EC%9D%B4%ED%8A%B8%EB%B8%8C%EB%A6%AC%ED%8A%BC_%EC%95%84%EC%9D%BC%EB%9E%9C%EB%93%9C_%EC%97%B0%ED%95%A9%EC%99%95%EA%B5%AD",
    "officialRecord": "그레이트브리튼 아일랜드 연합왕국에서 최초의 우표인 페니 블랙을 발행하다.",
    "yasaStory": "1840년 5월 1일 사건: 그레이트브리튼 아일랜드 연합왕국에서 최초의 우표인 페니 블랙을 발행하다.\n\n그레이트브리튼 아일랜드 연합왕국(United Kingdom of Great Britain and Ireland)은 1801년 연합법에 의해 그레이트브리튼 왕국과 아일랜드 왕국이 하나의 단일이자 주권국으로 통합되면서 수립되었다. 이 국가는 아일랜드 자유국이 독립을 쟁취한 1922년까지 이 형태로 지속되었으며, 그 잔여 지역은 그레이트브리튼 북아일랜드 연합왕국으로 이어졌다. 국가 성립 이전 수십 년 동안 시작된 급격한 산업화는 19세기 중반까지 계속되었다. 19세기 중반 정부의 무대응으로 악화된 아일랜드 대기근은 아일랜드 대부분 지역의 인구 붕괴를 초래했으며, 아일랜드 토지 개혁에 대한 요구를 증대시켰다. 19세기는 산업 혁명과 무역 및 금융의 성장기였으며, 영국은 세계 경제를 크게 지배했다. 대영제국령 해외 영토와 미국으로의 대규모 이주가 이루어졌다. 영국은 유럽 연안의 섬에서 나폴레옹 전쟁 동안 프랑스를 패배시킨 연합군에 자금을 지원했고, 지배적인 영국 왕립 해군을 발전시켜 대영제국이..."
