    "yasaStory": "1509년 4월 21일 사건: 헨리 8세가 잉글랜드 왕국의 왕위에 오르다.\n\n헨리 8세(Henry VIII, 1491년 6월 28일 ~ 1547년 1월 28일)는 헨리 7세 뒤를 이은 잉글랜드 국왕이다. 튜더가로서는 두 번째 국왕이었다. 헨리 8세는 여섯 번에 이르는 결혼과 이 과정에서 로마 가톨릭 교회와 불화 끝에 수장령을 통해 잉글랜드 교회를 분리 독립 시킨 것으로 유명하다. 헨리 8세는 교황 수위권에 대항하기 위해 왕권신수설로 자신의 행위를 정당화하였고 이를 바탕으로 전제군주로서 행동하였다. 종종 반대자에게 정치적 반역 혐의와 함께 이단 혐의를 씌웠고, 사권박탈법으로 피의자의 법적 지위를 박탈하여 정식 재판 없이 처형하였다. 헨리 8세는 토머스 울지, 토머스 모어, 토머스 크롬웰, 토머스 크랜머 등 두드러진 인물을 총리로 두어 통치하였으나 자신의 뜻과 맞지 않을 때는 추방하거나 처형하기를 서슴치 않았다. 로마 교황청으로 가던 교회의 수입 상당수가 왕실로 향하게 됨으로서 헨리 8세는 유래없는 자금을 확보할 수 있었으나, 사치스러운 생활과 비효율적 국정 운영..."
