    "yasaStory": "1916년 4월 24일 사건: 아일랜드 더블린에서 아일랜드인들이 영국에 대항해 부활절 봉기를 일으켰다.\n\n아일랜드(아일랜드어: Éire 에이레, 영어: Ireland, 음역어: 애란/애이란)는 유럽의 북서쪽 브리튼 제도에 있는 섬나라로 아일랜드섬 대부분을 차지하고 있다. 아일랜드라는 말은 지리적인 의미(아일랜드섬)와 혼동할 수 있으며, 아일랜드 공화국(아일랜드어: Poblacht na hÉireann 퍼블러흐트 너 헤이런 /ˈpˠɔbˠlˠəxt̪ˠ n̪ˠə ˈheːɾʲən̪ˠ/, 영어: Republic of Ireland 리퍼블릭 오브 아일랜드[*])이라는 명칭으로 사용하는 예가 많다. 아일랜드섬 안에서 북동쪽으로 영국(북아일랜드)과 국경을 마주하며, 동쪽은 아일랜드해, 서쪽은 대서양과 접하고 있다. 인구는 대략 500만 명이며, 유럽연합(EU), 경제 협력 개발 기구(OECD), 그리고 유엔(UN)의 구성원이다. 의원 내각제를 채택하고 있다, 2005년 이코노미스트지 조사 결과 삶의 질이 세계에서 제일 높다고 보고했으며, 2020년 기준 1인당 명목 GDP는 약 89,383달러, 인간..."
