    "yasaStory": "1961년 4월 27일 사건: 시에라리온, 영국에서 독립.\n\n시에라리온 공화국(영어: Republic of Sierra Leone)은 아프리카 대륙 서부 대서양 해안에 위치한 나라이다. 기니, 라이베리아와 국경을 접한다. 시에라리온은 아프리카에서 비교적 작은 나라의 하나로 71,740 km2의 면적이며 인구는 약 6,296,803 명이다.사바나 기후에서 우림까지 범위를 갖는 다양한 환경의 열대 기후를 지니고 있어, 우계에는 고온 다습하다. 프리타운은 수도, 정부의 소재지이자 가장 큰 도시이며, 보는 두 번째로 규모가 큰 도시이다. 인구 10만을 넘는 다른 주요 도시들은 케네마, 코이두, 마케니이다. 시에라리온은 1827년에 설립된, 서아프리카에서 가장 오래된 대학인 포라 베이 컬리지 (Fourah Bay College)와 세계에서 세 번째로 큰 천연 항구 엘리자베스 2세 부두 (Queen Elizabeth II Quay,QE II Quay,Deep Water Quay)가 있다. 이로 인해 ‘서아프리카의 아테네’라고 불린다. 시에라리온의 초기 거주자들은..."
