    "yasaStory": "1908년 4월 27일 사건: 1908년 런던 올림픽이 개최되다.\n\n1908년 하계 올림픽(영어: 1908 Summer Olympics, Games of the IV Olympiad)은 1908년 4월 27일부터 1908년 10월 31일까지 영국 런던에서 개최된 제4회 하계 올림픽이다. 원래는 이탈리아 로마에서 개최될 예정이었으나 1906년 베수비오산 분화 수습을 위한 재정 문제로 올림픽 개최를 포기하면서 런던에서 대신 개최하게 되었다. 로마는 훗날 1960년 하계 올림픽을 유치하게 된다. 4년 연속으로 치러지는 하계 올림픽의 네번째 대회로서 1906년 중간 올림픽으로 새로이 4년 주기의 대회를 시작하려던 분위기에서 벗어나 기존의 4년 주기를 확립한 대회이기도 했다. 당시 대회를 주관한 국제올림픽위원회 위원장은 피에르 드 쿠베르탱 백작이었다. 6개월 4일, 총 187일 동안 진행된 대회로서 근대 올림픽 역사상 가장 오랜 기간 동안 열린 대회이기도 하다. 이 대회부터 금, 은, 동메달 수여 제도가 도입되었으며, 여자 선수 출전규모도 확대되어 1896년..."
