    "yasaStory": "1910년 5월 6일 사건: 영국, 조지 5세가 국왕으로 즉위.\n\n조지 5세(영어: George V, 1865년 6월 3일 ~ 1936년 1월 20일)는 그레이트브리튼 아일랜드 연합 왕국의 왕족으로, 왕이자 그레이트브리튼 및 북아일랜드 연합 왕국 및 인도 제국의 황제이다. (재위 : 1910년 5월 6일 - 1936년 1월 20일) 빅토리아 여왕의 차손이자 영국의 전 국왕 엘리자베스 2세의 할아버지이다. 또한 러시아 제국의 차르 니콜라이 2세의 이종사촌 형이다. 보두앵, 알베르 2세의 8촌 형이기도 하다."
