    "officialRecord": "대영제국, 인도에서 인도인 용병들을 중심으로 하여 영국에 대항하는 세포이 항쟁이 일어나다.",
    "yasaStory": "1857년 5월 10일 사건: 대영제국, 인도에서 인도인 용병들을 중심으로 하여 영국에 대항하는 세포이 항쟁이 일어나다.\n\n대영제국(大英帝國, 영어: British Empire)은 영국 본국과 자치령, 식민지, 보호령, 위임통치령, 그리고 속령으로 구성된 정치 체제였다. 대영제국은 16세기 말부터 17세기 초에 잉글랜드 왕국이 건립한 해외 영토와 무역 거점에서 시작되었다. 19세기와 20세기에 전성기를 누린 대영제국은 역사상 가장 큰 제국이었고 가장 앞선 세계 강국이었다. 1913년 기준으로 대영제국은 4억 1천200만 명의 인구를 거느리고 있었는데, 이는 1913년 당시 전체 인구의 23%를 차지했다. 대영 제국은 1920년 3550만 제곱킬로미터의 영토를 보유했는데, 이는 전체 지구 면적의 24%를 차지한다. 이에 따라 영국의 정치 체제, 법 체계, 언어, 문화가 전 세계로 퍼지게 되었다. 대영제국이 전성기를 맞이했을 때 영국이 보유한 식민지 중 한 곳은 낮이었기 때문에 \"해가 지지 않는 나라\"라는 별명을 가지게 되었다. 대항해시대이던 15세기와 16세기 포르투갈 제국과 스페인 제국은 유럽인들의 세계..."
