    "yasaStory": "1941년 5월 10일 사건: 나치 독일의 루돌프 헤스가 독단으로 영국으로 건너가 평화를 제안하고 체포되었으며, 그는 이후 죽을 때까지 영국의 감옥에 갇히게 되다.\n\n나치 독일, 공식 명칭으로 독일국 또는 대독일국은 1933년부터 1945년까지 아돌프 히틀러와 나치당이 통제한 전체주의 독재 국가이다. 이 국가를 지칭하는 또다른 명칭인 제3제국은 나치가 자신들을 이전의 신성 로마 제국(800/962년~1806년)과 독일 제국(1871년~1918년)의 후계자임을 주장하면서 사용되었다. 1933년 히틀러가 집권하며 수립된 나치 독일은 스스로를 천년 제국이라고도 지칭했지만, 불과 12년 뒤 연합군이 베를린에 입성하며 제2차 세계 대전이 유럽에서 종전된 1945년 5월 국가가 해체되었다. 1933년 1월 30일 바이마르 공화국의 대통령 파울 폰 힌덴부르크가 히틀러를 총리로 임명한 이후, 나치당은 정치적 반대파를 제거하고 권력을 장악하기 시작했다. 1934년 8월 2일 힌덴부르크가 사망한 이후, 히틀러는 총리와 대통령직을 통합하여 퓌러라는 직위를 만들고 국민투표를 통해 취임했다. 이로써 독일의 권력은 히틀러 개인에게 집중되었으며, 그의 말은 곧 법이 되었고..."
