    "yasaStory": "1824년 5월 10일 사건: 영국, 런던에서 내셔널 갤러리가 개봉됐다.\n\n런던(London, 고대 영어: Lunden 룬덴, 라틴어: Londinium 론디니움[*])은 영국과 잉글랜드의 수도이자 최대 도시이다. 인구는 2014년 기준 8,538,689명으로 영국은 물론 유럽 전체 대도시권 중 가장 큰 권역이다. 런던은 템스강을 기반으로 2,000년 동안 발전해 왔으며 역사는 로마인들이 론디니움이라는 요새를 지은 때부터 시작되었다. 시티 오브 런던은 고대 시대부터 런던의 핵심 지역인데, 크기는 1.12-마일(2.9km2)로 중세 시대부터 변하지 않고 있으며 2011년을 기준으로 7,375명이 거주하고 있는 잉글랜드에서 가장 작은 도시이다. 적어도 19세기부터 \"런던\"이라는 용어는 주변 도시를 중심으로 개발된 대도시를 뜻했다. 이러한 광역 도시권의 대부분은 런던 지역과 그레이터 런던으로, 런던 시장과 런던 의회에서 통치한다. 런던은 도쿄, 뉴욕과 함께 세계적인 글로벌 도시 중 하나이며, 예술, 경제, 패션, 엔터테인먼트, 금융, 의료, 매체, 전문산업, 연구와..."
