    "category": "scandal",
    "interestScore": 90,
    "title": "잉글랜드 국왕 헨리 8세의 두 번째 부인 앤 불린이 불륜과 이단, 모반 등 죄목으로 처형당하다.",
    "source": "위키백과 · 잉글랜드 왕국",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%9E%89%EA%B8%80%EB%9E%9C%EB%93%9C_%EC%99%95%EA%B5%AD",
    "officialRecord": "잉글랜드 국왕 헨리 8세의 두 번째 부인 앤 불린이 불륜과 이단, 모반 등 죄목으로 처형당하다.",
    "yasaStory": "1536년 5월 19일 사건: 잉글랜드 국왕 헨리 8세의 두 번째 부인 앤 불린이 불륜과 이단, 모반 등 죄목으로 처형당하다.\n\n잉글랜드 왕국(Kingdom of England, 고대 영어: Engla rīce)은 여러 앵글로색슨 왕국들이 통합된 10세기 초부터 1707년 5월 1일까지 스코틀랜드 왕국과 연합하여 그레이트브리튼 왕국을 형성하기 전까지, 그레이트브리튼섬에 있던 주권 국가였다. 두 왕국이 통합된 그레이트브리튼 왕국은 이후 그레이트브리튼 아일랜드 연합왕국으로 발전하였다. 중세와 근세 동안 잉글랜드 왕국은 유럽에서 가장 강력한 국가 중 하나였다. 886년, 앨프레드 대왕은 덴마크 바이킹으로부터 런던을 재점령하였고, 이 사건 이후 그는 자신을 앵글로색슨인의 왕으로 선포하였으며, 899년에 사망할 때까지 그 지위를 유지하였다. 10세기 초에 앨프레드의 후손들인 장형왕 에드워드(899-924 재위)와 애설스탠(924-939 재위)는 다양한 앵글로색슨 왕국들이 통합하였고 이 결과 잉글랜드 왕국이 형성되었다. 927년, 애설스탠은 마지막으로 남은 바이킹 왕국 요르비크를 정복하며 잉글랜드 전역을 통치하는 최초의..."
