    "yasaStory": "1455년 5월 22일 사건: 장미 전쟁: 최초의 전투인 제1차 세인트올번스 전투에서 요크공 리처드가 헨리 6세를 이기고 포로로 잡다.\n\n장미 전쟁(영어: Wars of the Roses)은 붉은 장미를 표시로 삼은 랭커스터 왕가와 흰 장미를 표시로 삼은 요크 왕가 사이 왕위 쟁탈전이었다. 1455년부터 1485년까지 벌어졌다. 요크 공작 리처드는 헨리 6세의 발병을 틈타 1453년 호민관 겸 방위관이 되어 랭커스터가의 중심세력인 서머셋 공작과 싸워, 장미전쟁을 일으켜 그를 멸하였다. 1460년에 리처드는 왕위를 요구하여 헨리 6세의 사후 왕위 계승이 승인되었으나, 랭커스터파의 반대로 리처드는 전사하였다. 리처드의 아들 에드워드는 1461년 랭커스터가를 격파하고 왕위를 획득하여 에드워드 4세가 되었다. 이윽고 요크가 내부에 불화가 일어나, 1483년 에드워드 4세의 사후, 에드워드 5세와 그 동생이 에드워드 4세의 적자가 아니라는 명분으로 에드워드 4세의 동생 글로스터 공 리처드가 리처드 3세로서 즉위하였다. 이에 어머니 계통으로 왕실에 연결된 랭커스터가의 유일한 왕위 요구자인 헨리 튜더가 1485년 망명지인 프랑스에서..."
