    "yasaStory": "1738년 5월 24일 사건: 감리교회의 창시자인 존 웨슬리 잉글랜드 성공회 신부가 저녁에 회심하다.\n\n감리교회(監理敎會, 영어: Methodist Church, 감리교)는 성서를 중심으로 한 이성, 전통, 체험을 기독교의 근간으로 이해하는 복음주의적이며 경건한 신학적 입장을 가진 개신교 교파로 개신교 공교회주의를 따른다. 예배와 예식의 전통을 강조하며 성찬의 중요성을 강조하고, 성찬신학에 활력을 넣었으며, 야외 성찬과 함께 매주 성찬을 개신교 최초로 권고한 개신교 종파이다. 세계감리교협의회를 통해 전 세계의 감리교회 전통을 지닌 교단들이 소통하며, 전세계에서 활동한다. 신학적으로는 종교개혁가와 웨슬리의 전통을 수용하고 있으며, 교회 구조는 공교회(보편교회)의 구조인 감독제 교회이다. 지역을 중심으로 한 지방회의 감리사, 대규모 구역인 연회에 감독이 있는 교회구조를 가졌다. 감독은 선거를 통해 선출되며 연회의 성직자 안수와 주요 의사결정을 내린다. 18세기 잉글랜드 성공회의 성직자였고 신학자인 존 웨슬리(영어: Rev. John Wesley)의 복음주의 운동과 사회복음 운동, 부흥 운동인..."
