    "yasaStory": "1979년 7월 12일 사건: 키리바시가 영국으로부터 독립하다.\n\n키리바시 공화국(영어: Republic of Kiribati 리퍼블릭 오브 키리배스[*], 키리바시어: Ribaberiki Kiribati 리파페리키 키리파스, 문화어: 키리바티), 약칭 키리바시(영어: Kiribati 키리배스[*], 키리바시어: Kiribati 키리파스)는 오세아니아의 미크로네시아에 있는 나라이다. 수도는 사우스타라와(과거에는 타라와)이며 공용어는 영어이다. 날짜 변경선의 가장 동쪽에 있는 국가이다. 따라서 일출 시각이 제일 빠른 국가이다. 중부 태평양의 서쪽에 있는 섬나라로, 1788년 영국 해군 대령 토머스 길버트(Thomas Gilbert)가 길버트 제도에 상륙한 뒤 영국의 식민지화가 시작되었다. 1916년 길버트 제도와 엘리스 제도가 영국에 병합되었고 1971년 모두 자치권을 얻었다. 1978년 엘리스 제도가 투발루로 분리된 후 1979년 7월 독립하였다. 1892년 영국의 보호령이 되었다가 1979년 독립하였다. 제2차 세계 대전 중에 키리바시의 옛 수도인..."
