    "yasaStory": "1431년 5월 30일 사건: 백년 전쟁: 잔다르크가 프랑스 루앙에서 19살의 나이로 잉글랜드 왕국의 종교재판에 따라 화형을 당하다.\n\n백년 전쟁(영어: the Hundred Years' War, 프랑스어: la guerre de Cent Ans)은 1337년부터 1453년까지 116년이라는 기간 동안 잉글랜드 왕국의 플랜태저넷 가와 프랑스 왕국의 발루아 가 사이에 프랑스 왕위 계승 문제를 놓고 일어난 일련의 분쟁들을 총체적으로 부르는 이름이다. 플랜태저넷 가와 발루아 가 양측 모두 여러 동맹자들을 전쟁에 끌어들였다. 중세 유럽에서 가장 유명한 전쟁 중 하나로, 서유럽에서 가장 넓은 땅의 왕위를 두고 두 왕조가 5대 117년에 걸쳐 싸운 장대한 전쟁이다. 기사의 최고 전성기이자 동시에 기사계급의 쇠퇴가 시작된 시기이며, 잉글랜드와 프랑스 양국 모두 전쟁으로 인해 강고한 국민정체성이 싹트이게 됐다. 1066년, 노르만인의 잉글랜드 정복 이래로 잉글랜드 국왕은 프랑스 땅에 보유한 영지에 대하여 프랑스 국왕의 명목상 제후였다. 프랑스의 역대 국왕들은 수 백년에 걸쳐 잉글랜드 국왕의 영지를 빼앗아 왔으며, 백년전쟁 당시 즈음에는..."
