    "yasaStory": "2006년 6월 4일 사건: 대한민국 축구 국가대표팀이 스코틀랜드 에딘버러 이스터 로드 경기장에서 펼쳐진 가나와의 평가전에서 1 대 3으로 패배하였다.\n\n대한민국 축구 국가대표팀은 대한민국의 성인 남성 축구 국가대표팀으로 대한축구협회에 의해 구성된다. 국제 축구 연맹에서는 Korea Republic으로 호칭되며 1948년 하계 올림픽에서 처음 국제 무대에 발을 내디뎠고 1954년 FIFA 월드컵을 통해 처음 FIFA 월드컵 본선 무대를 밟은 이후 1986년 FIFA 월드컵부터 2026년 FIFA 월드컵까지 아시아 최초이자 세계에서 6번째로 11회 연속 본선에 진출했다. 2024년 8월 기준으로 총 11번 월드컵에 출전했고 2002년 FIFA 월드컵에서 최종 순위 4위를 달성하며 아시아 축구 연맹 회원국 중 월드컵 최다 출전 및 최고 성적을 보유하고 있다. 2002년 월드컵에서 최초로 월드컵 준결승전에 진출한 아시아 축구 연맹 회원국 기록을 세웠고 2024년 기준으로 월드컵 준결승전에 진출한 유일한 아시아 축구 연맹 회원국 기록을 보유하고 있다. 월드컵 본선 통산 성적은 7승 10무 21패로 6승은 유럽 대표팀(폴란드, 포르투갈, 이탈리아..."
