    "yasaStory": "1844년 6월 6일 사건: 기독교청년회(YMCA)가 런던에서 설립되다.\n\n기독교청년회(YMCA, Young Men's Christian Association)는 영국의 복음주의자들이 1844년 결성한 기독교 민간단체이다. 세계 120개국, 1만여 개의 조직이 있으며, 한국에서는 개화기 때인 1903년 10월에 창립한 대한기독교청년회연맹이 한국 YMCA의 시작이며, 월남 이상재 선생이 참여했다. 처음부터 빠르게 성장했고 궁극적으로 근육적 기독교 원칙에 기초한 세계적인 운동이 되었다. 지역 YMCA는 운동 시설 제공, 다양한 기술 강습 개최, 기독교 홍보, 인도주의 활동 등 다양한 청소년 활동을 통해 청소년 개발에 초점을 맞춘 프로젝트와 서비스를 제공한다. YMCA는 비정부 연맹으로, 각각의 독립된 지역 YMCA가 국가 조직에 소속되어 있다. 국가 조직은 지역 연합(유럽, 아시아 태평양, 중동, 아프리카, 라틴 아메리카 및 카리브해 지역, 미국 및 캐나다)과 세계 YMCA 연합(세계 YMCA)의 일부이다. 결과적으로 모든 YMCA는 고유하며 Paris Basis와..."
