    "title": "청나라와 러시아, 미국, 영국, 프랑스 사이에 '''톈진 조약'''이 체결되다.",
    "source": "위키백과 · 청나라",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%B2%AD%EB%82%98%EB%9D%BC",
    "officialRecord": "청나라와 러시아, 미국, 영국, 프랑스 사이에 '''톈진 조약'''이 체결되다.",
    "yasaStory": "1858년 6월 13일 사건: 청나라와 러시아, 미국, 영국, 프랑스 사이에 '''톈진 조약'''이 체결되다.\n\n대청국(大淸國, 만주어: ᡩᠠᡳᠴᡳᠩᡤᡠᡵᡠᠨ 다이칭 구룬, 1636년 4월~ 1912년 2월 12일), 또는 대청제국(大淸帝國), 청조(淸朝), 대청(大淸), 약칭 청(淸)은 중국 역사상 최후의 통일 왕조이자, 만주족이 세운 마지막 황조였다. 청나라는 대청(大淸) 으로 명명된 이후 11명의 황제가 즉위했다. 건주 여진족 지도자 4명과 후금 군주 1명이 사후 대청 황제 로 추대되었다."
