    "officialRecord": "영국의 리처드 2세가 농민반란의 지도자들을 만나다.",
    "yasaStory": "1381년 6월 14일 사건: 영국의 리처드 2세가 농민반란의 지도자들을 만나다.\n\n리처드 2세(Richard II, 1367년 1월 6일 ~ 1400년 2월 14일, 재위 1377년 6월 22일 ~ 1399년 9월 30일)는 플랜태저넷 왕가의 잉글랜드 8번째 왕으로, 흑태자 에드워드의 아들이다."
