    "lunarDate": "양력 6월 15일",
    "category": "episode",
    "interestScore": 90,
    "title": "영국 바클레이즈 그룹의 자산운용사 '바클레이즈 글로벌 인베스터스(BGI)'가 미국 글로벌 자산…",
