    "yasaStory": "1961년 6월 19일 사건: 쿠웨이트가 영국으로부터 독립하다.\n\n쿠웨이트(아랍어: الكويت)는 서아시아에 있는 입헌군주국이다. 정식 명칭은 쿠웨이트국(아랍어: دولة الكويت 다울라트 알쿠와잇[*], 영어: State of Kuwait)이며 수도는 쿠웨이트시티이다. 과거 영국령의 일부였다. 사우디아라비아, 이라크와 국경을 접한다. 공용어는 아랍어이며 면적은 레바논과 크기가 비슷하다. 해안선은 약 500 km로, 이란과바다를 통해 국경을 맞대고 있다. 인구의 대부분은 수도인 쿠웨이트시티 주변에 모여산다. 2023년 기준으로 쿠웨이트의 인구는 482만명인데, 153만명만 쿠웨이트 시민으로 나머지는 외국인이다. 현재 쿠웨이트의 영토는 과거 메소포타미아였다. 1938년 유전이 발견되기 전에는 지방의 무역항으로 있었으며, 유전의 개발로 인해 1946년부터 1982년까지 급속도로 근대화와 경제성장을 이루어냈다. 1980년대에는 쿠웨이트 증시의 대폭락으로 경제 위기를 겪었다. 1990년에는 사담 후세인의 지시를 받은 이라크 군대의 공격을 받아 괴뢰국인..."
