    "yasaStory": "1837년 6월 20일 사건: 빅토리아 여왕이 영국 왕위를 승계받다.\n\n빅토리아 여왕(영어: Victoria, 1819년 5월 24일~1901년 1월 22일)는 그레이트브리튼 아일랜드 연합 왕국의 여왕(1837~1901)이다. 켄트와 스트래선 공작 에드워드와 빅토리아 폰 작센코부르크잘펠트 공녀의 외동딸이다. 전 영국 여왕 엘리자베스 2세의 고조모이다."
