    "officialRecord": "아르헨티나와 잉글랜드의 1986년 FIFA 월드컵 경기 도중 신의 손 사건 발생. 경기결과는 디에고 마라도나의 맹활약으로 아르헨티나가 잉글랜드를 2:1로 꺾고 4강에 진출함.",
    "yasaStory": "1986년 6월 22일 사건: 아르헨티나와 잉글랜드의 1986년 FIFA 월드컵 경기 도중 신의 손 사건 발생. 경기결과는 디에고 마라도나의 맹활약으로 아르헨티나가 잉글랜드를 2:1로 꺾고 4강에 진출함.\n\n1986년의 아르헨티나 대 잉글랜드는 아르헨티나와 잉글랜드의 1986년 FIFA 월드컵 8강전 경기를 가리킨다. 아르헨티나의 디에고 마라도나가 이 경기에서 기록한 터뜨린 첫 번째 골은 마라도나가 골키퍼와 헤딩 경합하면서 손으로 공을 건드리는 반칙을 했으나 주심은 이를 득점으로 인정했다. 신의 손이라고 부르는 이 사건은 아르헨티나와 잉글랜드 축구 팀 사이의 라이벌 관계를 상징적으로 잘 드러내는 사건 중의 하나이다. 이 사건이 일어난 6월 22일은 마라도나교의 오순절이다."
