    "yasaStory": "1713년 6월 23일 사건: 아카디아의 프랑스인 거주민들이 양국으로부터 영국에 충성을 맹세하거나 캐나다 노바스코샤주에서 떠나라는 요구를 받다. [http://www.acadian-cajun.com/acadia5.htm]\n\n아카디아(영어: Acadia 어케이디아[*]) 또는 아카디(프랑스어: Acadie 아카디[*])는 북아메리카 북동부의 옛 프랑스 식민지를 부르던 이름이다. 퀘벡주의 동쪽과 노바스코샤주, 뉴브런즈윅주, 프린스에드워드아일랜드주, 뉴펀들랜드 래브라도주, 그리고 미국의 뉴잉글랜드 지역이 여기에 해당한다."
