    "title": "영국의 유럽연합 탈퇴의 여부를 결정하는 투표인 브렉시트가 거행되었다.",
    "source": "위키백과 · 영국",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%98%81%EA%B5%AD",
    "officialRecord": "영국의 유럽연합 탈퇴의 여부를 결정하는 투표인 브렉시트가 거행되었다.",
    "yasaStory": "2016년 6월 23일 사건: 영국의 유럽연합 탈퇴의 여부를 결정하는 투표인 브렉시트가 거행되었다.\n\n그레이트브리튼 북아일랜드 연합왕국, 약칭 영국(英國)은 유럽 본토 해안에서 북서쪽으로 떨어진 곳에 위치한 섬나라이자 입헌군주국이다. 북해, 영국 해협, 아일랜드해 및 대서양에 접했으며 그레이트브리튼섬의 잉글랜드, 스코틀랜드, 웨일스 및 아일랜드섬 북부의 북아일랜드로 네 개의 구성국이 연합해 형성한 단일 국가이다. 수도는 런던이고 스코틀랜드, 웨일스, 북아일랜드의 수도는 각각 에든버러, 카디프, 벨파스트이다. 아일랜드섬의 영국령인 북아일랜드는 아일랜드와 국경을 맞대며 해외 영토까지 포함 시 스페인(영국령 지브롤터), 키프로스(아크로티리 데켈리아)와 국경을 공유한다. 건지섬, 저지섬, 맨섬과 같이 본토의 일부는 아니나 영국의 군주가 지배하는 왕실속령들도 있다. 해외 영토 거주민들과 영국 본토 국민들은 서로 지역에 거주할 권리가 없으며 상호 간 이민도 자유롭지 않다. 영국은 입헌군주제를 기본으로 하여 근대적 의회제도와 의원내각제를 전 세계로 전파한 국가이며 산업혁명의 발원지로 제일 먼저 산업화를..."
