    "officialRecord": "세이셸이 영국으로부터 독립했다.",
    "yasaStory": "1976년 6월 29일 사건: 세이셸이 영국으로부터 독립했다.\n\n세이셸 공화국(세이셸 크리올: Repiblik Sesel 레피블리크 세셀, 프랑스어: République des Seychelles 레퓌블리크 드스 세이셸스[*], 영어: Republic of Seychelles, 문화어: 세이쉘) 또는 줄여서 세이셸은 아프리카 동부 인도양에 위치한, 155개의 섬으로 구성된 섬나라이자 군도 국가이다. 수도이자 최대 도시인 빅토리아는 본토 아프리카에서 동쪽으로 1500 km 떨어져 있다. 인접한 섬나라 및 영토로는 몰디브, 코모로, 마다가스카르, 모리셔스 및 프랑스의 해외 데파르트망인 마요트와 레위니옹이 남쪽에 있고, 차고스 제도가 동쪽에 있다. 세이셸은 아프리카에서 가장 작은 나라이자 인구가 가장 적은 아프리카 국가이며, 2022년 추정 인구는 100,600명이다. 세이셸은 16세기에 유럽인들이 발견하기 전까지는 사람이 살지 않았다. 이후 프랑스와 영국이 대립하다가 19세기 초 영국이 완전한 통제권을 확보하게 된다. 1976년 영국으로부터 독립을 선언한..."
