    "officialRecord": "블렌하임 전투에서 말버러 공작과 사부아 공자 외젠이 이끌었던 잉글랜드, 신성로마제국 연합군이 프랑스, 바바리아 연합군을 격파하다. 이 전투는 스페인 왕위계승전쟁의 중요한 전환기를 마련하였다.",
    "yasaStory": "1704년 8월 13일 사건: 블렌하임 전투에서 말버러 공작과 사부아 공자 외젠이 이끌었던 잉글랜드, 신성로마제국 연합군이 프랑스, 바바리아 연합군을 격파하다. 이 전투는 스페인 왕위계승전쟁의 중요한 전환기를 마련하였다.\n\n블레넘 전투(영어: Battle of Blenheim) 또는 제2차 회흐슈테트 전투(독일어: Zweite Schlacht bei Höchstädt)-는 1704년 8월 13일 스페인 왕위 계승 전쟁의 주요 전투이다. 프랑스의 루이 14세는 합스부르크 오스트리아의 수도 빈을 포위함으로써 신성로마제국의 황제 레오폴트 1세를 스페인 왕위 계승 전쟁에서 떨어져 나가게 하고 유리한 평화협정을 맺으려 하였다. 프랑스의 마르생 원수와 바이에른의 바이에른 선제후의 연합군은 오스트리아의 서쪽에서 위협을 가했고, 이탈리아 북부에 배치된 방돔(Vendôme) 원수의 프랑스-스페인 연합군은 브레너 가도(Brenner Pass)를 통해 오스트리아를 공격할 가능성이 있었다. 또한 오스트리아의 동쪽에서는 라코치 페렌츠 2세(Rákóczi)의 헝가리 반란군이 존재하고 있었다. 이로 인해 빈은 세 방향에서 압박을 받고 있었다. 이 위협을 해소하기 위해 오스트리아의 동맹국인 영국의 말버러 공작(Duke of Marlborough..."
