    "yasaStory": "1940년 8월 12일 사건: 독일, 영국 본토 공습 개시.\n\n독일연방공화국, 약칭 독일은 중앙유럽에 위치한 국가이다. 인구는 2025년 유엔 인구조사 기준 84,075,075 명으로 유럽에서 러시아, 튀르키예 다음으로 인구가 많은 국가로 유럽 연합(EU) 회원국 중 인구가 가장 많은 국가이다. 또 유럽 국가 중 인구밀도가 높은 국가 중 하나이다. 북쪽으로 발트해, 북해와 남쪽으로 알프스산맥의 사이에 위치하며, 북쪽으로 덴마크, 동쪽으로 폴란드와 체코, 남쪽으로 오스트리아와 스위스, 서쪽으로는 베네룩스 3국과 프랑스와 접해 있다. 영토는 357,022 km2이며 기후는 주로 온대 기후를 보인다. 공용어는 독일어이고, 그 외에 소수 민족들의 언어인 러시아어, 영어, 소르브어, 덴마크어, 프리지아어 등도 쓰인다. 독일의 수도면서 가장 인구가 많은 도시는 베를린이고, 주요 금융 중심지는 프랑크푸르트, 가장 큰 광역도시권은 루르이다. 현대 독일 지역에 대한 정착은 전기 구석기 시대부터 시작되었으며, 신석기 시대 이후로는 주로 켈트족이 정착하였다. 이후..."
