    "title": "IRA의 폭탄 테러로 마운트배튼 경을 포함한 4명이 아일랜드 슬라이고에서 사망했다. 그리고 북…",
    "source": "위키백과 · 아일랜드 공화국군 임시파",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%95%84%EC%9D%BC%EB%9E%9C%EB%93%9C_%EA%B3%B5%ED%99%94%EA%B5%AD%EA%B5%B0_%EC%9E%84%EC%8B%9C%ED%8C%8C",
    "officialRecord": "IRA의 폭탄 테러로 마운트배튼 경을 포함한 4명이 아일랜드 슬라이고에서 사망했다. 그리고 북아일랜드 워런포인트에서 18명의 영국군이 사망했다.",
    "yasaStory": "1979년 8월 27일 사건: IRA의 폭탄 테러로 마운트배튼 경을 포함한 4명이 아일랜드 슬라이고에서 사망했다. 그리고 북아일랜드 워런포인트에서 18명의 영국군이 사망했다.\n\n아일랜드 공화국군 임시파(아일랜드어: Óglaigh na hÉireann, 영어: Provisional Irish Republican Army, PIRA)은 1947년 조직된 아일랜드의 무장 테러 단체이다. 흔히 IRA라 함은 이 PIRA를 지칭하는 말이다. 이들은 아일랜드 공화국, 영국, 미국 등을 포함한 세계 여러 나라에서 무장 테러 단체로 인식되고 있다. 이들 스스로는 자신들이 아일랜드 독립전쟁 당시 영국 식민통지자들에 대항해 싸운 IRA의 후계자라 하지만 절대다수의 아일랜드인은 이 주장을 받아들이지 않는다. 이들은 북아일랜드에서의 영국군 철수와 북아일랜드와 아일랜드 공화국과의 통일 아일랜드 건설을 목표로 하고 있다. 이 단체는 OIRA와는 성향이 다른 과격파적 무장단체이다. 주 임무는 해외의 영국 공관 폭파, 영국 정치인, 영국에 협조하는 아일랜드인 암살 등이며, PIRA가 가장 많은 테러 활동을 벌인 곳은 영국의 통치를 받는 북아일랜드였으며, 영국을 비롯한 아일랜드 공화국,..."
