    "officialRecord": "영국의 웨일스 공비 다이애나, 파리에서 자동차 사고로 사망.",
    "yasaStory": "1997년 8월 31일 사건: 영국의 웨일스 공비 다이애나, 파리에서 자동차 사고로 사망.\n\n웨일스 공비 다이애나(영어: Diana, Princess of Wales, 1961년 7월 1일~1997년 8월 31일 음7.29)는 영국의 전 왕세자빈이자 현재 영국의 왕위 계승 순위 1위인 웨일스 공 윌리엄과 5위인 서식스 공작 해리의 어머니이다. 본명은 다이애나 프랜시스(Diana Frances)이며 결혼 전의 성씨는 스펜서(Spencer)이다. 스펜서 백작가의 제8대 백작인 존 스팬서와 프랜시스 로슈의 삼녀이다. 1981년 7월 29일 웨일스 공 찰스와 결혼하여 웨일스 공 윌리엄과 서식스 공작 해리를 낳았다. 그러나 부부간의 불화와 불륜 문제 등으로 1992년부터 별거에 들어갔고, 1996년 8월 28일 최종 이혼 절차를 밟았다. 뛰어난 미모와 패션 감각으로 언론의 많은 주목을 받던 인물이었으며 또한 그녀의 사생활은 파파라치와 황색언론의 집요한 관심의 대상이 되기도 하였다. 찰스 왕세자의 결혼 후 왕태자비 신분으로 지뢰 제거 운동, 결식아동 돕기 등 여러 자선활동을 펼쳤다. 1997년..."
