    "officialRecord": "최초의 대륙회의가 미국 펜실베이니아주 필라델피아에서 비밀리에 소집되어 영국의 압제로부터의 식민지 권리와 자유 수호와 영국과의 통상단절을 결의하다.",
    "yasaStory": "1774년 9월 5일 사건: 최초의 대륙회의가 미국 펜실베이니아주 필라델피아에서 비밀리에 소집되어 영국의 압제로부터의 식민지 권리와 자유 수호와 영국과의 통상단절을 결의하다.\n\n대륙회의(大陸會議, Continental Congress)는 영국 본국의 고압적인 식민지 경영에 북아메리카 13주 자치 의식이 높아지면서 1774년부터 개최한 회의다. 각 식민지 대표가 참석하였다. 제1차 대륙회의와 제2차 대륙회의가 있다. 미국 독립 승인 후 연합회의(1781년 -1789년)로 발전하지만, 이 연합회의를 포함하여 대륙회의라고 총칭할 수 있다."
