    "officialRecord": "잉글랜드의 메리 1세, 잉글랜드 왕국 및 아일랜드 왕국의 여왕으로 즉위.",
    "yasaStory": "1553년 7월 19일 사건: 잉글랜드의 메리 1세, 잉글랜드 왕국 및 아일랜드 왕국의 여왕으로 즉위.\n\n메리 1세(Mary I, 1516년 2월 18일 ~ 1558년 11월 17일)는 잉글랜드 튜더 왕조의 여왕이다. 당시 잉글랜드의 군주는 아일랜드의 군주를 겸했기 때문에 메리 1세 역시 잉글랜드 왕국 및 아일랜드 왕국의 여왕으로 재위하였다. 메리 1세는 헨리 8세와 아라곤 왕녀 카탈리나 사이에서 태어났다. 둘 사이에는 메리에 앞서 1511년 태어난 콘월 공작 헨리가 있었으나 태어난 지 한 달을 넘기지 못하고 사망하였기 때문에 메리 1세가 사실상 맏이였다. 헨리 8세는 후계로 아들을 간절히 원했고, 카탈리나가 폐경을 맞아 더 이상 임신을 할 수 없게 되자 파혼하였다. 헨리 8세가 카탈리나와 결혼을 무효라 선언하였지만, 교황 클레멘스 7세가 이를 인정하지 않자, 헨리 8세는 수장령을 통해 잉글랜드 교회를 로마 가톨릭교회에서 분리하여 잉글랜드 종교 개혁을 촉발하였다. 이 사건으로 메리 1세는 왕위 계승권이 박탈되었다가 훗날 복권되었다. 헨리 8세 수장령에도 어머니의 영향 아래 교육받은 메리..."
