    "yasaStory": "1978년 7월 25일 사건: 세계 최초의 시험관 아기인 루이즈 브라운이 영국에서 태어나다.\n\n시험관내수정(in vitro fertilisation, IVF, 체외수정) 또는 시험관 아기는 불임의 치료 방법 중 하나로 난자와 정자를 체외에서 수정시켜 자궁에 착상시켜 임신에 이르게 하는 시술 방법이다. 1978년 7월 25일 세계 최초의 시험관 아기인 루이스 브라운이 영국에서 태어났고, 1985년 10월 12일 서울대학교 의과대학 연구팀(장윤석 교수팀)이 한국 최초로 시험관 아기 출산에 성공하였다."
