    "officialRecord": "미국, 영국, 중화민국 3개국이 포츠담 선언을 하다.",
    "yasaStory": "1945년 7월 26일 사건: 미국, 영국, 중화민국 3개국이 포츠담 선언을 하다.\n\n미합중국(영어: United States of America/United States, USA/US, 한국 한자: 美合衆國), 약칭 미국(영어: America, 한국 한자: 美國)은 50개의 주와 특별구 1개로 이루어진 연방제 공화국이다. 태평양에 위치한 하와이를 제외한 모든 주와 수도인 워싱턴 D.C.는 북아메리카 대륙에 위치하며, 북쪽으로는 캐나다와 남쪽으로는 멕시코와 국경에 맞닿는다. 또한 북서측에 위치한 알래스카주는 동측으로 캐나다와 서측으로 베링 해협을 사이로 러시아와 마주한다. 플로리다반도의 남동쪽으로는 바하마와 쿠바가 있다. 미국은 태평양과 카리브해에 해외 영토를 보유한다. 세계 여러 나라 중에 미국은 총면적 기준으로 세 번째로 넓은 국가이고, 북아메리카 및 아메리카 대륙에서 인구가 가장 많은 국가이자 세계에서 세 번째로 인구가 많은 국가이다. 세계에서 손꼽는 다문화 국가 중 하나이며, 주로 백인, 흑인, 아시아인 등 여러 인종들이 섞여 있으며 그중에서 백인이 가장 많다..."
