    "yasaStory": "1965년 7월 26일 사건: 몰디브가 영국으로부터 독립했다.\n\n몰디브 공화국(디베히어: ދިވެހިރާއްޖޭގެ ޖުމްހޫރިއްޔާ 디베히라제게 줌후리야, 영어: Republic of Maldives, 문화어: 말디브 제도 공화국), 약칭 몰디브(디베히어: ދިވެހިރާއްޖެ 디베히라제, 영어: Maldives, 영국식 영어 발음: /ˈmɔːldiːvz/, 문화어: 말디브)는 남아시아 인도양에 있는 섬나라로, 인도와 스리랑카 서남쪽에 있다. 국토는 남북으로 길게 늘어선 26개의 환초로 이루어져 있으며, 섬의 총개수는 1,192개이다. 수도인 말레는 군주제 시절에 술탄이 왕궁을 짓고 다스리던 곳이다. 매년 100만명 이상의 사람이 방문하는 유명 관광지이다."
