    "yasaStory": "1954년 7월 29일 사건: 반지의 제왕의 첫 책인 《반지 원정대》가 영국에서 출간되다.\n\n《반지의 제왕》(영어: The Lord of the Rings, 약자 LotR, 斑指의帝王)은 존 로널드 루엘 톨킨이 지은 3부작 판타지 소설이다. 이 소설은 클라이브 스테이플스 루이스의 《나니아 연대기》, 어슐러 르 귄의 《어스시 시리즈》와 함께 세계 3대 판타지 소설로 꼽힌다. 반지의 제왕은 톨킨의 이전 작품인 《호빗》의 다음편으로서 이후에 벌어지는 더 많은 이야기를 다루고 있다. 이 소설은 1937년과 1949년 사이에 창작되었고, 소설을 쓰는 동안에 제2차 세계 대전이 벌어졌다. 원래는 한권으로 계획되었지만, 1954년과 1955년에 세 권으로 출판되었다. 여러 번에 걸쳐서 재발행되었으며 수많은 언어로 번역되어, 20세기 문학 중 가장 잘 알려지고 영향력 있는 책으로 손꼽히고 있다."
