    "yasaStory": "1966년 7월 30일 사건: 1966년 FIFA 월드컵에서 잉글랜드가 웸블리 경기장에서 독일을 4:2로 이기고 영어권 국가 최초로 월드컵에서 우승하였다.\n\n1966년 FIFA 월드컵(영어: FIFA World Cup 1966)은 제8회 FIFA 월드컵으로 1966년 7월 11일부터 7월 30일까지 잉글랜드에서 개최되었다."
