    "title": "제3차 십자군 원정: 잉글랜드의 리처드 1세가 아르수프 전투에서 살라딘을 패배시킴",
    "source": "위키백과 · 십자군",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%8B%AD%EC%9E%90%EA%B5%B0",
    "officialRecord": "제3차 십자군 원정: 잉글랜드의 리처드 1세가 아르수프 전투에서 살라딘을 패배시킴",
    "yasaStory": "1191년 9월 7일 사건: 제3차 십자군 원정: 잉글랜드의 리처드 1세가 아르수프 전투에서 살라딘을 패배시킴\n\n십자군 전쟁(영어: Crusades)은 중세 라틴 교회의 공인을 받은 원정대와 이슬람 군대 사이에 레반트 지역의 지배권을 놓고 벌어진 종교전쟁(교황의 권력을 찾기 위한 전쟁)이다. 좁은 의미의 십자군이라고 하면 성지를 이슬람 세력으로부터 탈환하기 위해 지중해 동해안 지역에서 진행된 전쟁들을 가리키나, 넓은 의미에서 중세의 기독교회에서 주동한 다른 전쟁들을 십자군으로 보는 관점 또한 존재한다. 이교도나 이단의 토벌, 가톨릭 집단 내부의 분쟁, 정치적 이득 등 전쟁의 동기는 매우 다양했다. 십자군 시대에는 '십자군'이라는 말이 존재하지 않았으며, 1760년경을 전후하여 처음 사용례가 나타난다. 1095년 교황 우르바노 2세가 클레르몽 공의회에서 제1차 십자군을 소환한 것을 최초의 십자군으로 본다. 당시 아나톨리아를 정복하고 있던 튀르크족에게 위협을 느낀 동로마 제국(비잔티움 제국)의 황제 알렉시오스 1세를 위한 군사원조가 그 명분이었다. 우르바노 2세의 목적 중 하나는 무슬림들이 지배하고..."
