    "officialRecord": "제2차 세계 대전: 나치 독일이 57일간의 런던 야간 폭격을 시작(영국 본토 항공전)",
    "yasaStory": "1940년 9월 7일 사건: 제2차 세계 대전: 나치 독일이 57일간의 런던 야간 폭격을 시작(영국 본토 항공전)\n\n제2차 세계 대전(한국 한자: 第二次世界大戰, 영어: World War II, Second World War, WWII/WW2)은 1939년 9월 1일부터 1945년 9월 2일까지 일어났던 세계 대전이다. 당시 강대국 전부와 세계 대부분의 국가가 전쟁에 개입해 연합국과 추축국이라는 적대적인 두 군사동맹이 생겨났다. 제2차 세계 대전은 30개국 이상에서 1억명이 넘는 군인이 직접 참전한 총력전이다. 세계 대전 참전국은 총체적인 경제적, 산업적, 과학적 역량을 전부 전쟁 수행에 쏟아 부어 민간 자원과 군사 자원의 경계가 모호해졌다. 항공기도 전쟁에서 중요한 역할을 맡아 항공기를 통해 인구 밀집지대의 전략폭격이 수행되었고 유일하게 실전 사용된 핵무기 2발도 배치하고 투하하는 데 항공기가 사용되었다. 제2차 세계 대전은 인류 역사상 사망자가 가장 많은 전쟁으로 총 사망자는 7,500만명 정도로 추정되며 이 중 대부분이 민간인이었다. 또한 수천만 명이 홀로코스트를 포함한 대량학살, 기아, 학살..."
