    "officialRecord": "무굴 제국 멸망. 이후 인도는 영국 식민지로 편입되다.",
    "yasaStory": "1858년 9월 8일 사건: 무굴 제국 멸망. 이후 인도는 영국 식민지로 편입되다.\n\n무굴 제국은 근세 남아시아에 존재했던 이슬람 제국이다. 전성기에는 인도 아대륙의 서북부인 인더스강 유역과 중남부 아프가니스탄에서부터 카슈미르를 지나 동쪽으로는 오늘날의 아삼주 및 방글라데시 저지대까지, 남쪽으로는 남인도의 데칸고원까지 이르는 광활한 영토를 통치하였다. 무굴 제국은 중앙아시아의 군벌이었던 바부르가, 이웃한 사파비 제국과 오스만 제국의 도움을 받아 1526년 파니파트 제1차 전투에서 델리 술탄국의 술탄 이브라힘 로디를 격파하고 북인도 평원을 장악하며 건국되었다. 바부르의 손자 악바르 시기부터 시작된 제국의 전성기는 마지막 위대한 황제였던 아우랑제브가 사망한 1720년까지 지속되었으며, 그의 통치 기간 동안 제국은 영토적으로 최대 범위에 도달했다. 그러나 아우랑제브 치세에 실시된 인두세 부활과 이슬람으로의 개종을 강요하는 종교적 억압책으로 인해 제국의 분열이 심화되었다. 또한 아우랑제브가 전개하는 다양한 정복 사업은 국가 재정에 큰 타격을 주었고, 이는 세금 액수의 증가로..."
