    "yasaStory": "2022년 9월 8일 사건: 영국 찰스 3세 국왕 즉위.\n\n찰스 3세(영어: Charles III, 1948년 11월 14일~)는 영국과 14개국으로 이루어진 영연방 왕국의 국왕이다. 휘는 찰스 필립 아서 조지 마운트배튼윈저(영어: Charles Philip Arthur George Mountbatten-Windsor)이다. 그는 1952년부터 2022년 그의 즉위에 이르기까지 콘월 공작과 로스시 공작의 후계자였으며 영국 역사상 가장 오랫동안 왕세자의 자리에 있던 인물이다. 그는 1958년 7월부터 어머니인 엘리자베스 2세가 즉위한 이후 2022년 9월 8일에 승하할 때까지 웨일즈에 가장 오래 군림한 공작이었다. 조지 6세(1936년~1952년)가 즉위한 이후로 70년 만에 첫 남성 국왕이다. 엘리자베스 2세의 아들로써 유일한 남성 국왕에 즉위를 하였다. 그의 자녀는 웨일스 공 윌리엄과 서식스 공작 해리가 있다. 역대 영국 국왕 중에서 가장 최고령의 나이에 즉위한 국왕이다. 엘리자베스 2세와 에든버러 공작 필립의 장남이다. 찰스 3세는 버킹엄..."
