    "officialRecord": "유고슬라비아(현 크로아티아) 자그레브 상공에서 영국과 유고슬라비아 국적 여객기가 충돌하여 176명 사망함.",
    "yasaStory": "1976년 9월 10일 사건: 유고슬라비아(현 크로아티아) 자그레브 상공에서 영국과 유고슬라비아 국적 여객기가 충돌하여 176명 사망함.\n\n유고슬라비아(직역: '남슬라브족의 땅')는 1918년부터 1992년까지 존재했던 동남유럽과 중앙유럽의 국가였다. 제1차 세계 대전 이후, 임시 슬로벤인 크로아트인 세르브인국이 세르비아 왕국에 합병되면서 세르브인 크로아트인 슬로벤인 왕국이라는 이름으로 수립되었으며, 오스만 제국과 합스부르크 군주국이 수세기 동안 이 지역을 지배한 후 주권 국가로서 남슬라브족의 최초의 연합을 구성하였다. 페타르 1세는 첫번째 군주였다. 이 나라는 1922년 7월 13일 파리에서 열린 대사회담에서 국제적으로 인정받았다. 1929년 10월 3일, 국호를 유고슬라비아 왕국으로 변경하였다. 1941년 4월, 왕국은 추축국의 침공을 받아 점령당했다. 1943년, 파르티잔 저항 세력은 민주연방 유고슬라비아를 선포하였다. 1944년, 당시 망명 중이었던 페타르 2세는 이를 합법적인 정부로 인정하였다. 1945년 11월, 공산주의 정부가 선출된 후 군주제는 폐지되었고, 국호는 유고슬라비아 연방인민공화국으로 변경되었다...."
