    "yasaStory": "1898년 9월 19일 사건: 영국과 프랑스의 식민정책이 아프리카에서 충돌한 파쇼다 사건 발생\n\n파쇼다 사건(Fashoda Incident)은 파쇼다 위기(프랑스어: Crise de Fachoda)라고도 불리며, 1898년 7월 10일부터 11월 3일까지 동아프리카에서 벌어진 영국과 프랑스 간의 제국주의적 영토 분쟁의 절정이 된 사건이다. 백나일강의 파쇼다로 향한 프랑스 원정대는 상나일강 유역의 통제권을 확보하여 영국을 수단에서 배제하려 시도했다. 프랑스군과 영국-이집트 연합군(프랑스군보다 10배 많은 병력)은 우호적인 태도로 만났으나 유럽에서는 전쟁 공포로 번졌다. 양 제국은 양측의 격렬한 수사 속에서 전쟁 직전까지 치달았다. 거센 압박 끝에 프랑스는 철수하였고, 이 지역에 대한 영-이집트의 통제권이 확립되었다."
