    "yasaStory": "1919년 9월 19일 사건: 아프가니스탄, 영국으로부터 독립.\n\n아프가니스탄 이슬람 토후국(파슈토어: د افغانستان اسلامي امارت 더 아프가니스탄 이슬라미 이마라트, 다리어: امارت اسلامی افغانستان 이마라티 이슬라미이 아프가니스탄, 문화어: 아프가니스탄 이슬람 추장국), 약칭 아프가니스탄(파슈토어·다리어: افغانستان)은 남아시아에 있는 나라이다. 내륙국으로 북쪽은 투르크메니스탄·우즈베키스탄·타지키스탄, 북동쪽은 중화인민공화국, 동쪽과 남쪽은 파키스탄, 서쪽은 이란과 맞닿아 있다. 수도는 카불이다. 다민족 국가로서 주류 민족인 파슈툰족을 비롯해 타지크족, 하자라족, 우즈베크인, 아이마크인 등이 거주한다. 역사적으로 중동과 아시아의 여러 지역의 문화가 만나는 곳이었으며, 여러 세기를 거쳐 다양한 민족들의 고향이 되었다. 전략적인 위치로 인해 수많은 군사 활동이 이루어진 곳이 되기도 했는데, 대표적인 정복 세력으로는 알렉산더 대왕, 이슬람 제국, 몽골 제국, 대영제국, 소련, 그리고 현대의 서방 세력에 이른다...."
