    "officialRecord": "영국의 토마스쿡 항공이 파산되었다",
    "yasaStory": "2019년 9월 23일 사건: 영국의 토마스쿡 항공이 파산되었다\n\n토머스 쿡 항공(영어: Thomas Cook Airlines)은 영국의 전세 항공사로 총 95개 노선을 취항하고 있다. 본사는 영국 맨체스터에 위치해 있으며 2008년에 설립했다. 또한 사용하고 있는 허브 공항으로 벨파스트 인터내셔널 공항, 버밍엄 공항, 브리스톨 인터내셔널 공항, 카디프 국제공항, 이스트 미들랜드 공항, 런던 개트웍 공항, 글래스고 공항, 런던 스탠스테드 공항, 리즈 브래드포드 공항, 맨체스터 공항, 뉴캐슬 공항이 있다."
