    "yasaStory": "1907년 9월 26일 사건: 뉴질랜드와 뉴펀들랜드가 영국의 자치령이 되다.\n\n뉴질랜드(영어: New Zealand) 또는 아오테아로아(마오리어: Aotearoa)는 오세아니아의 폴리네시아(또는 오스트랄라시아)에 위치한 섬나라이자 왕정 주권국이다. 뉴질랜드는 북섬과 남섬, 그리고 600여 개의 작은 섬들로 구성되어 있다. 뉴질랜드의 총 육지 면적은 268,000km²이다. 뉴질랜드는 오스트레일리아와 태즈먼해를 사이에 두고 2,000km 정도 떨어져 있고 뉴칼레도니아, 피지, 통가와 같은 태평양 북서부의 도서와는 남쪽으로 1,000km 이상 떨어져 있다. 방위로는 동경174도에서 남위 41도에 있다. 지리적 고립으로 인해 뉴질랜드는 인간이 정착한 마지막 땅이 되었다. 또한 오랜 고립 기간 동안, 뉴질랜드에서는 독특한 생물적 다양성이 발전했다. 뉴질랜드의 다양한 지형과 높은 봉우리들은 화산 폭발과 육지의 융기로 인해 형성된 경우가 많다. 뉴질랜드의 수도는 웰링턴이고, 인구가 가장 많은 도시는 오클랜드이다. 1250년과 1300년 사이에 뉴질랜드의 섬에 폴리네시아인이..."
