    "sillokUrl": "https://ko.wikipedia.org/wiki/%ED%99%8D%EC%BD%A9_%EB%B0%98%ED%99%98_%ED%98%91%EC%A0%95",
    "officialRecord": "영국과 중화인민공화국, 홍콩 반환 협정에 가조인.",
    "yasaStory": "1984년 9월 26일 사건: 영국과 중화인민공화국, 홍콩 반환 협정에 가조인.\n\n홍콩 반환 협정(-返還協定)은 1984년 12월 19일 중화인민공화국과 영국 정부가 홍콩의 이양을 결정한 협정으로, 중영 공동 성명(中英共同聲明, 영어: Sino-British Joint Declaration, 중국어 간체자: 中英联合声明, 정체자: 中英聯合聲明, 병음: Zhōng-Yīng Liánhé Shēngmíng)이라고 부르기도 한다. 정식 명칭은 홍콩 문제에 관한 중화인민공화국 정부와 그레이트브리튼 북아일랜드 연합 왕국 정부의 공동 성명이다. 홍콩은 1842년 아편 전쟁 이후 영국과 청나라 사이에 맺은 난징 조약으로 홍콩 섬이 영국에 빼앗긴 것이며, 1860년에는 베이징 조약으로 가우룽반도 남단부가 영구히 영국령이 됐고 1898년에는 신제 지구를 99년간 영국이 지배한 것이다. 1982년 9월 영국 마거릿 대처 총리의 중화인민공화국 방문 기간 동안에 양국 지도자는 홍콩 문제에 대해 토의하고 각자의 입장을 천명하는 한편, 외교채널을 통해서 계속 상의하는 것에 합의했다. 이에 따라..."
