    "yasaStory": "1066년 9월 28일 사건: 노르만인의 잉글랜드 정복: 정복왕 윌리엄이 600여 척의 배를 이끌고 잉글랜드를 침략하다.\n\n노르만인의 잉글랜드 정복(Norman conquest of England)은 11세기에 노르망디 공작 윌리엄 1세, 일명 정복왕 윌리엄이 이끄는 노르만인, 브르타뉴인이 앵글로색슨 잉글랜드를 침공하여 정복한 사건이다. 윌리엄은 자식 없이 죽은 잉글랜드의 에드워드 참회왕과 자신의 친척 관계를 근거로 들며 잉글랜드 왕위를 주장했다. 참회왕은 1066년 죽었으며 그의 매제 고드윈의 아들 해럴드가 왕위를 계승했다. 1066년 9월, 노르웨이 국왕 하랄드 하르드라디가 잉글랜드 북부에 상륙, 풀퍼드 전투에서 잉글랜드군에게 승리를 거두었다. 그러나 해럴드는 9월 25일 스탬퍼드브리지 전투에서 하르드라디를 꺾었고 하르드라디는 이 전투에서 사망했다. 그로부터 며칠 되지 않아 윌리엄이 잉글랜드 남부에 상륙했고, 해럴드는 병력 상당수를 북부에 남겨둔 채 윌리엄과 대적하기 위해 남하했다. 해럴드의 수비군은 윌리엄의 침략군과 10월 14일 헤이스팅스 전투에서 격돌했고, 그 결과 윌리엄이 승리하고 해럴드는 사망했다..."
