    "yasaStory": "1890년 9월 29일 사건: 영국 성공회 소속 찰스 존 코르프(한국명:고요한) 주교가 조선 선교를 목적으로 인천항으로 입국\n\n영국 성공회는 다음을 가리킨다. 영국은 총 4개 성공회 관구의 관리 하에 놓여 있다. 잉글랜드 성공회(잉글랜드) 스코틀랜드 성공회(스코틀랜드) 웨일스 성공회(웨일스) 아일랜드 성공회(북아일랜드)"
