    "yasaStory": "1966년 9월 30일 사건: 보츠와나 공화국(당시 베추아날란드 보호국)이 영국으로부터 독립하다.\n\n보츠와나 공화국(영어: Republic of Botswana 리퍼블릭 오브 부츠와나[*], 츠와나어: Lefatshe la Botswana [lɪˈfatsʰɪ la bʊˈtswana] 리파치 라 부츠와나), 줄여서 보츠와나(영어·츠와나어: Botswana 부츠와나[*], 문화어: 보쯔와나)는 아프리카 남부에 있는 내륙 국가이자 영연방의 구성국으로 수도는 가보로네이며 영토의 대부분은 칼라하리 사막이기 때문에 최소 인구수를 자랑하고 있으며 모리셔스 다음으로 아프리카에서 민주주의 지수가 가장 높은 국가로도 알려져 있다."
