    "source": "위키백과 · 7년 전쟁",
    "sillokUrl": "https://ko.wikipedia.org/wiki/7%EB%85%84_%EC%A0%84%EC%9F%81",
    "officialRecord": "7년 전쟁: 영국과 스페인 간 마닐라 전투에 영국이 승리한다.",
    "yasaStory": "1762년 10월 6일 사건: 7년 전쟁: 영국과 스페인 간 마닐라 전투에 영국이 승리한다.\n\n7년 전쟁(영어: Seven Years' War, 독일어: Siebenjähriger Krieg 지벤예리거 크리크[*], 1756년 ~ 1763년)은 오스트리아 왕위계승전쟁에서 프로이센에게 패배해 독일 동부의 비옥한 슐레지엔을 빼앗긴 오스트리아 합스부르크가가 그곳을 되찾기 위해 프로이센과 벌인 전쟁을 말한다. 이 전쟁에는 유럽의 거의 모든 열강이 참여하게 되어 유럽뿐 아니라 그들의 식민지가 있던 아메리카와 인도에까지 퍼진 세계대전급의 대규모 전쟁이었다. 인도의 무굴 제국이 프랑스의 지지를 받으며, 영국에 의한 벵골 지방의 침공을 저지하려고 했다. 주로 오스트리아-프랑스-작센-스웨덴-러시아가 동맹을 맺어 프로이센-하노버-영국의 연합에 맞섰다. 유럽에서는 영국의 지원을 받은 프로이센이 최종적으로 승리를 거두어 슐레지엔의 영유권을 확보했으며, 식민지 전쟁에서는 영국이 주요 승리를 거두어 북아메리카의 뉴프랑스(현재의 퀘벡주와 온타리오주)를 차지하여 북아메리카에서 프랑스 세력을 몰아냈고, 인도에서도..."
