    "yasaStory": "1970년 10월 10일 사건: 피지가 영국으로부터 독립했다.\n\n피지 공화국(영어: Republic of Fiji 리퍼블릭 오브 피지[*], 피지어: Matanitu ko Viti 마타니투 코 비치, 피지 힌디어: फ़िजी गणराज्य, Fijī Gaṇarājya 피지 가나라지아)는 오세아니아의 멜라네시아에 있는 섬나라이다. 뉴질랜드에서 북동쪽으로 1,100 해리 (2,000 km; 1,300 mi)에 위치한다. 330여개의 섬과 500여개의 암초로 이루어져 있으며, 개중 110여개에 사람이 살고 있다. 총 면적은 18,300 제곱킬로미터 (7,100 sq mi)이다. 전체 인구 924,610명 중 약 87%의 인구가 비치레부섬과 바누아레부섬에 나뉘어 살고 있는데, 전체 인구의 75%는 수바, 난디, 라우토카 등 비치레부섬 해안가에 살고 있다. 비치레부섬 중심부는 지세가 좋지 않아 사람이 살기 힘들다. 피지 군도의 섬 대부분은 1억 5천만년 전 화산활동으로 형성되었다. 오늘날에도 비치레부섬과 타베우니섬에서 지질활동이 활발히 일어나고 있다. 기원전..."
