    "officialRecord": "영국 핵실험이 사우스오스트레일리아주 에뮤 필드에서 실시되다.",
    "yasaStory": "1953년 10월 15일 사건: 영국 핵실험이 사우스오스트레일리아주 에뮤 필드에서 실시되다.\n\n핵무기 실험(核武器實驗, 영어: nuclear weapons testing, 문화어: 핵시험 核試驗)은 핵무기에 대한 실험을 말한다. 20세기 이후 핵무기를 개발한 대부분의 나라들은 핵실험 단계를 거쳤다. 핵실험 과정을 통해 무기의 성능과 특성에 대한 정보를 얻을 수 있다. 추가적으로 핵실험은 과학력과 군사력을 과시하는 정치적 이유에서 시도되기도 했다. 미국의 첫 원자폭탄 실험은 1945년 7월 16일의 트리니티 실험으로 약 20 킬로톤의 성능이었다. 첫 번째 수소폭탄인 아이비 마이크의 실험은 1952년 11월 1일 마셜 제도의 에네웨타크 환초에서 실시되었다. 가장 큰 폭탄은 1961년 소비에트 연방이 실시한 50 메가톤 규모의 차르 봄바의 실험이다. 1963년 미국, 소련, 영국이 대기권과 수중, 우주에서의 핵실험을 금지하는 부분적 핵실험 금지 조약에 서명했다. 이 조약은 지하 핵실험만을 허용하고 있다. 프랑스는 1974년, 중국은 1980년까지 대기권 핵실험을 계속했다. 지하 핵실험은..."
