    "sillokUrl": "https://ko.wikipedia.org/wiki/%EB%A9%94%EC%9D%B8%EC%A3%BC",
    "officialRecord": "영국이 메인주 포틀랜드를 불태우다.",
    "yasaStory": "1775년 10월 16일 사건: 영국이 메인주 포틀랜드를 불태우다.\n\n메인주(영어: State of Maine)는 미국 북동부 뉴잉글랜드의 가장 북쪽에 있는 주이다. 남쪽과 동쪽은 대서양에 닿아 있으며, 북동쪽은 캐나다의 뉴브런즈윅주, 북서쪽은 퀘벡주와 국경을 접한다. 서쪽으로는 뉴햄프셔주와 접한다. 부통령 해니벌 햄린의 정치적 고향이다. 한때 메인 주의 선거인단은 10명이었으나 현재는 4명 (승자독식 2명+의회 선거구 2명)으로 줄어들었다. 주민들의 전반적인 정치적 성향은 민주당에 가깝다. 반면 메인 2구는 점차 공화당에 가까워지고 있다. 미국에서 백인 비율이 가장 높은 주이다. 현 주지사는 2019년에 취임한 자넷 밀스이다."
