    "officialRecord": "영국 의회가 첫 만남을 가지다.",
    "yasaStory": "1707년 10월 23일 사건: 영국 의회가 첫 만남을 가지다.\n\n그레이트브리튼 북아일랜드 연합왕국 의회(Parliament of the United Kingdom of Great Britain and Northern Ireland), 줄여서 영국 의회(Parliament)는 영국 및 왕실속령하고 해외영토의 최고 입법부이다. 양원제 구성으로, 상원인 귀족원(House of Lords)하고 하원인 서민원(House of Commons)으로 이루어져 있으며, 모두 런던의 웨스트민스터궁을 국회의사당으로 사용하고 있다. 귀족원은 성직귀족하고 세속귀족으로 구성되어 있다. 성직귀족은 잉글랜드 성공회의 대주교가 대부분이며, 세속귀족은 일대귀족과 세습귀족 92인으로 다시 나뉜다. 일대귀족은 국왕이 직접 귀족으로 임명한 의원이며, 세습귀족은 왕가 직책을 역임하고 있거나 동료 세습귀족에 의해 선출되는 의원이다. 2009년 영국 대법원 개원 이전에는 귀족원이 사법귀족을 통해 사법권을 행사하기도 하였다. 서민원(하원)은 총선거를 통해 선출된 국회의원 650인으로 구성된다..."
