    "yasaStory": "1945년 10월 24일 사건: 유엔 창설. 뉴질랜드, 니카라과, 덴마크, 도미니카 공화국, 미국, 벨라루스, 레바논, 룩셈부르크, 사우디아라비아, 시리아, 아르헨티나, 아이티, 엘살바도르, 영국, 이란, 이집트, 중화민국, 칠레, 쿠바, 터키, 파라과이, 폴란드, 프랑스, 필리핀이 유엔에 가입하다.\n\n유엔(영어: UN) 또는 국제연합(國際聯合, 영어: United Nations 유나이티드 네이션스[*], , 러시아어: Организация Объединённых Наций 오르가니자치야 오비예디뇬니흐 나치[*], 중국어: 联合国, 병음: Liánhéguó 롄허궈[*], 스페인어: Organización de las Naciones Unidas 오르가니사시온 데 라스 나시오네스 우니다스[*], 아랍어: الأمم المتحدة 알우맘 알무타히다[*], 문화어: 련합국기구)은 국제 평화와 안전을 보장하고, 국제 협력 증진, 인권 개선 등의 활동을 통해 세계의 번영을 추구하는 국제 기구이다. 또한 UN은 전세계 거의 모든 국가를 아우르는 국제 기구이며, 1945년 10월 24일에 제2차 세계대전 종전 이후 출범했다. 설립 목적은 국제법, 국제적 안보 공조, 경제 개발 협력 증진, 인권 개선으로 세계 평화를 유지하는데 있다. 현재 유엔 가입국가의 수는 총 193개국이다. 동일 영문은 제2차..."
