    "yasaStory": "1964년 10월 24일 사건: 잠비아가 영국으로부터 독립했다.\n\n잠비아 공화국(Republic of Zambia)은 아프리카에 있는 내륙국으로 수도는 루사카이다. 북쪽으로 콩고 민주 공화국, 북동쪽으로 탄자니아, 동쪽으로 말라위, 남쪽으로 모잠비크, 짐바브웨, 보츠와나, 나미비아, 서쪽으로 앙골라와 국경을 접한다."
