    "officialRecord": "조지 3세가 영국의 왕으로 즉위.",
    "yasaStory": "1760년 10월 25일 사건: 조지 3세가 영국의 왕으로 즉위.\n\n조지 3세(영어: George William Frederick, 1738년 6월 4일 ~ 1820년 1월 29일)는 1760년 10월 25일부터 그레이트브리튼 왕국과 아일랜드의 국왕이었고, 1800년 연합법이 제정된 이후 1801년 1월 1일부터 1820년 사망할 때까지 그레이트브리튼 아일랜드 연합 왕국의 왕이 되었다. 영국의 왕으로 재임하는 동안 그는 신성 로마 제국에 속한 브라운슈바이크뤼네부르크 선제후국의 선제후이자 공작이었으며, 1814년 10월 12일 하노버 왕국이 수립되면서 하노버의 국왕을 겸임했다. 조지 3세는 하노버가의 3번째 영국 군주였지만, 이전의 국왕과는 달리 그는 제1언어로 영어를 썼으며, 영국에서 태어난 군주였고, 하노버를 한번도 방문하지 않았다. 그의 일생과 재위 기간은 이전 영국 왕들에 비해 훨씬 길었으며, 그 대부분은 영국과 하노버가 개입된 분쟁으로 점철되었다. 초기에 그레이트브리튼 왕국은 프랑스를 7년 전쟁에서 격파해 북아메리카와 인도에서 우위를 점하는 유럽..."
