    "officialRecord": "영국의 소설가 찰스 디킨스는 자신의 대표작인 《위대한 유산》을 'All the Year Round' 잡지에 처음으로 실었다.",
    "yasaStory": "1860년 12월 1일 사건: 영국의 소설가 찰스 디킨스는 자신의 대표작인 《위대한 유산》을 'All the Year Round' 잡지에 처음으로 실었다.\n\n찰스 존 허펌 디킨스(영어: Charles John Huffam Dickens, 문화어: 챨즈 디킨즈, 1812년 2월 7일 - 1870년 6월 9일)는 영국의 소설가이자 사회 비평가이다. 그는 세계에 가장 널리 알려진 소설 속의 인물을 만들어냈고, 빅토리아 시대를 대표하는 영국의 소설가가 되었다. 화가 로버트 시모어의 만화를 위해 쓰기 시작한 희곡 소설 《The Pickwick Papers(원제:The Posthumous Papers of the Pickwick Club)》(픽윅 보고서)를 분책(分冊)으로 출판하여 일약 유명해졌다. 그는 특히 가난한 사람에 대한 깊은 동정을 보이고, 사회의 악습에 반격을 가하면서, 사회에 실상에 대한 묘사를 이야기 형식으로 완성했다. 후기 소설에는 초기의 넘치는 풍자는 약해졌으나, 구성의 치밀함과 사회 비평의 심화는 주목할 만하다. 그의 작품으로 자전적 요소가 짙은 《데이비드 코퍼필드》, 《위대한 유산》 등을 비롯 《올리버 트위스트》, 《크리스마스..."
