    "yasaStory": "1936년 12월 11일 사건: 에드워드 8세 퇴위로 인해 동생 조지 6세, 영국 국왕으로 즉위.\n\n에드워드 8세(Edward VIII, 1894년 6월 23일 ~ 1972년 5월 28일)는 1936년 1월 20일부터 1936년 12월 11일까지 그레이트브리튼 및 북아일랜드 연합왕국의 국왕이자 인도 제국의 황제(영어: King of the United Kingdom of Great Britain and Northern Ireland and Emperor of India)였다. 본명은 에드워드 앨버트 크리스천 조지 앤드루 패트릭 데이비드 윈저(영어: Edward Albert Christian George Andrew Patrick David Windsor)이다. 미국 출신의 이혼여성인 월리스 워필드 심슨(Wallis Warfield Simpson)과 결혼하고자 했으나 많은 사람들이 반대하자 왕위를 남동생인 조지 6세에게 물려주고 에드워드 8세에서 윈저 공으로 신분이 바뀐 사건으로 유명하다. 정치적으로는 제2차 세계 대전 당시 적성국가인 나치 독일을 지지하여 영국 왕실에서 에드워드 8세..."
