    "officialRecord": "영국 런던에 스모그 현상. 이날부터 5일 연속 계속된 이 현상으로 4,000여 명이 죽음.",
    "yasaStory": "1952년 12월 5일 사건: 영국 런던에 스모그 현상. 이날부터 5일 연속 계속된 이 현상으로 4,000여 명이 죽음.\n\n스모그(영어: smog)는 대기 오염의 하나이다. 스모크(smoke)와 포그(fog)가 결합된 말로 원래는 연기와 안개가 섞인 것을 가리키는 말이었지만, 현대에 와서 대기 오염 물질로 하늘이 뿌옇게 보이는 현상을 부르는 말로 쓰이게 되었다. 자동차 배기 가스나 화력 발전소·공장 등에서 나오는 대기 오염 물질 때문에 생긴다. 대도시에서 많이 생기지만, 바람에 실려가 다른 곳에 피해를 주기도 한다."
