    "officialRecord": "영국의 후원으로 \"유대인들의 고향인 팔레스타인에 유대 국가를 설립할 것\"이라는 내용의 밸푸어 선언이 발표되다.",
    "yasaStory": "1917년 11월 2일 사건: 영국의 후원으로 \"유대인들의 고향인 팔레스타인에 유대 국가를 설립할 것\"이라는 내용의 밸푸어 선언이 발표되다.\n\n유대인(단수: 히브리어: יְהוּדִי 예후디, 복수: 히브리어: יְהוּדִים 예후딤) 또는 유태인(猶太人)은 히브리 민족에서 기원한 민족적, 종교적, 문화적 집단이다. 유대인에게 있어서 유대 민족성과 종교는 매우 밀접한 관계인데 이는 유대교가 유대 민족의 전통적인 신앙이기 때문이다. 유대인은 과거에 어떤 민족에서 종교로 묶여서 나온 집단에 가까워서 민족보다 종교를 중시했었다. 유대교로의 개종자들은 보통 유대인 사회 내에서 태어날 때부터 유대인이었던 이들과 동등한 지위를 갖는다. 주류 유대교에서 개종은 권장되는 것은 아니며 어려운 일로 여겨진다. 주로 유대인과 비유대인과의 결혼이 이에 해당된다. 성서에 따르면 유대 민족은 고대 가나안의 족장이던 아브라함에게서 유래되었다. 이집트에 의해 잔혹한 정복과 학살을 당한 유대인들은 이집트에서 대대로 노예 민족으로 살며 탄압받다가 이집트인들이 끝내 유대인 남자는 아기까지 다 죽이고 여자들만 남겨 멸족시키려 하자 출애굽을 거쳐 가나안에 다시..."
