    "source": "위키백과 · 스파이스 걸스",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%8A%A4%ED%8C%8C%EC%9D%B4%EC%8A%A4_%EA%B1%B8%EC%8A%A4",
    "officialRecord": "전 세계 31개국 차트 1위, 영국 뮤지션으로는 드물게 미국 빌보드차트 정상에 올랐던 스파이스 걸스의 대표곡 〈Wannabe〉가 수록된 데뷔 앨범 Spice가 발매되다.",
    "yasaStory": "1996년 11월 4일 사건: 전 세계 31개국 차트 1위, 영국 뮤지션으로는 드물게 미국 빌보드차트 정상에 올랐던 스파이스 걸스의 대표곡 〈Wannabe〉가 수록된 데뷔 앨범 Spice가 발매되다.\n\n스파이스 걸스(영어: Spice Girls)는 1994년 영국에서 결성된 팝 걸 그룹이다. 그룹은 제리 할리웰(\"진저 스파이스\"), 멜러니 C(\"스포티 스파이스\"), 빅토리아 베컴(\"포쉬 스파이스\"), 멜러니 B(\"스캐리 스파이스\"), 엠마 번튼(\"베이비 스파이스\")의 5인조 멤버로 구성되어 있다. 그들은 버진 레코드와 계약을 해 1996년 발매된 데뷔 싱글 \"Wannabe\"는 전 세계 31개국에서 정상을 차지하며 메가 히트를 기록하였고, 세계적으로 큰 명성을 얻었다. 그들의 데뷔 정규 앨범 Spice는 전 세계에서 3,000만장 이상의 판매량을 기록하였는데, 이는 걸 그룹 역사상 최고 판매량 기록이다. 그들의 다음 앨범 Spiceworld는 2,000만장 이상의 판매량을 기록했다. 스파이스 걸스는 전 세계적으로 총 8,500만 장이 넘는 음반 판매고를 올려 역사상 세계에서 가장 높은 판매고를 올린 걸 그룹으로 기록되었고, \"비틀즈 열풍\" 이후 가장 큰 영국의 팝 문화 현상이었다. 그들은..."
