    "officialRecord": "제1차 세계 대전: 영국-프랑스, 對 오스만 제국 선전포고. 키프로스 합병 선언.",
    "yasaStory": "1914년 11월 5일 사건: 제1차 세계 대전: 영국-프랑스, 對 오스만 제국 선전포고. 키프로스 합병 선언.\n\n제1차 세계 대전(第一次世界大戰, 영어: World War I, First World War, WWI/WW1)은 1914년 7월 28일부터 1918년 11월 11일까지 일어난 유럽을 중심으로 한 세계 대전이다. 1914년 오스트리아-헝가리가 세르비아에게 선전포고를 하며 시작되었고, 1918년 독일의 항복으로 끝이 났다. 제2차 세계 대전이 발생하기 전까지는 단순히 세계 대전(世界大戰, 영어: World War) 또는 대전쟁(大戰爭, 영어: Great War)이라고 불렸다. 미국에서는 처음에 유럽 전쟁(영어: European War)이라고 불렸다. 제1차 세계 대전으로 병사 990만명 이상이 사망했다. 기술 및 산업의 고도화와 전술적 교착 상태로 인해 사상자 비율이 악화되었다. 제1차 세계 대전은 사망자가 많았던 전쟁 중 하나이며, 참전국의 수많은 혁명 등을 포함하여 주요한 정치적 변화가 일어났다. 이 전쟁은 전 세계의 경제를 두 편으로 나누는 거대한 강대국 간 동맹끼리 일어난 충돌이다..."
