    "yasaStory": "1884년 11월 6일 사건: 영국, 뉴기니섬을 보호령화.\n\n뉴기니섬(영어: New Guinea, 톡 피신: Niugini, 히리 모투: Niu Gini, 문화어: 뉴기니아 섬)은 오스트레일리아 북쪽에 있는 섬이자 그린란드에 이어 세계에서 두 번째로 큰 섬이다. 오세아니아에 속한다. 오스트레일리아와는 기원전 5000년 경 토레스 해협으로 나뉘었다. 인도네시아에서는 파푸아섬(인도네시아어: Pulau Papua) 또는 이리안섬(Pulau Irian)으로 불린다. 동경 141°를 기준으로 동부는 파푸아뉴기니의 영토이고, 서부는 인도네시아의 영토(서뉴기니)이다. 명목상 뉴기니섬은 파푸아뉴기니의 영토이다."
