    "officialRecord": "유엔 총회서 미국-영국 등 60개국, 원자력 평화이용 공동결의안 제출.",
    "yasaStory": "1954년 11월 6일 사건: 유엔 총회서 미국-영국 등 60개국, 원자력 평화이용 공동결의안 제출.\n\n원자력(原子力, 영어: atomic energy), 핵발전(核發電, 영어: nuclear power)이란 방사성원소의 원자핵 붕괴(방사선 붕괴 포함) 또는 원자핵의 질량 변화에 의해 방출되는 에너지를 동력자원으로 활용하는 경우를 말하며, 일반적으로 핵분열과 핵융합 과정을 통해 에너지를 생산하는 방식이 알려져 있다. 원자력이 처음 규명된 이후 군사(핵무기), 의학(방사선 치료기), 발전(전기 생산), 가속기(과학적 연구), 산업(비파괴 검사) 등 다양한 분야에서 이용되고 있으며, 그 중에서도 가장 널리 이용되고 있는 분야가 발전이다. 핵에너지 생성의 3가지 유형인 핵분열, 핵융합, 방사성 붕괴 중에서 현재 원자력발전에 이용되는 것은 핵분열 방식이다. 핵융합 방식은 아직 연구 단계에 있으며, 방사성 붕괴에 의한 핵에너지는 그 양이 상대적으로 미량이어서 직접 발전에 이용하기 힘들다. 따라서 우라늄 같은 방사성 물질을 원자로에서 인공적으로 분열시켜 나오는 원자력 에너지로 발전을 한다. 사실..."
