    "yasaStory": "1639년 11월 24일 사건: 영국의 천문학자 제러마이아 호록스가 금성의 태양면 통과를 처음으로 관찰하다.\n\n제러마이아 호록스(Jeremiah Horrocks, 1618년 ~ 1641년 1월 3일)는 영국의 천문학자로, 금성 일면통과의 첫 번째 관찰자이다."
