    "title": "영국의 과학자 찰스 다윈이 《종의 기원》을 출간하다.",
    "source": "위키백과 · 종의 기원",
    "sillokUrl": "https://ko.wikipedia.org/wiki/%EC%A2%85%EC%9D%98_%EA%B8%B0%EC%9B%90",
    "officialRecord": "영국의 과학자 찰스 다윈이 《종의 기원》을 출간하다.",
    "yasaStory": "1859년 11월 24일 사건: 영국의 과학자 찰스 다윈이 《종의 기원》을 출간하다.\n\n《종의 기원에 대하여》(영어: On the Origin of Species, On the Origin of Species by Means of Natural Selection, the Preservation of Favoured Races in the Struggle for Life)는 찰스 다윈의 저술로서 1859년 11월 24일에 출판되었고, 진화생물학의 토대로 여겨지는 과학문헌이다. 자연선택을 통한 종의 진화에 대한 이론을 제시했다. 이 책은 출간 즉시 당시의 종교적인 믿음과 모순된다는 이유로 큰 논쟁을 일으켰다. '종의 기원' 초판은 1500권이 제작되었고, 하루 만에 다 팔렸다. 이중 500권은 머디의 공공대출도서관이 구입해갔다."
