    "yasaStory": "2017년 12월 31일 사건: 호주 시드니 뉴사우스웨일스주 코완 크릭 예루살렘 베이에서 de Havilland Canada DHC-2 Beaver 수상 경비행기(1963년 제작)가 강으로 추락, 세계 최대 케이터링(출장 연회 서비스) 업체인 영국 컴퍼스그룹(Compass Group)의 CEO인 포함 가족 5명, 조종사 1명 등 탑승자 6명이 사망하였다.\n\n시드니(Sydney, /ˈsɪdni/)는 오스트레일리아의 뉴사우스웨일스주의 주도이자 오스트레일리아의 최대 도시이다. 오세아니아에서 인구가 가장 많은 도시로 알려져 있다. 오스트레일리아의 동해안에 있는 시드니는 시드니항을 중심으로 서쪽으로는 블루마운틴스, 북쪽으로는 헉스베리시, 남쪽으로는 로열 국립공원, 서남쪽으로는 매카서까지 총 70 km 길이로 뻗어 있다. 시드니는 총 658개 교외촌으로 이루어져 있으며 33개 지방 자치 단체를 포함하고 있다. 시드니에 사는 주민을 흔히 \"시드니사이더즈\"(Sydneysiders)라고 부른다. 2021년 인구 조사에 따르면 대 시드니에 거주하는 인구는 5,231,150명이며 뉴사우스웨일스주 인구의 약 66%를 차지한다. 시드니의 별명으로는 \"에메랄드 시티\"(Emerald City)나 \"하버 시티\"(Harbour City)가 있다. 오스트레일리아 원주민은 약 3만년 전부터 대시드니 지역에 살고 있었으며, 시드니 곳곳에서 원주민의 암각화와 문화 유적지를..."
