    "yasaStory": "1894년 12월 22일 사건: 드레퓌스 사건: 유대계 프랑스인인 프랑스 육군 장교 알프레드 드레퓌스가 반역 누명을 쓰고 종신형을 선고받음\n\n드레퓌스 사건(Dreyfus Affair)이란 보불전쟁 후 19세기 후반 프랑스를 휩쓸었던 군국주의, 반유대주의, 강박적인 애국주의 때문에 억울하게 옥살이를 한 프랑스 포병대위 드레퓌스의 간첩혐의를 놓고 프랑스 사회가 무죄를 주장하는 드레퓌스파와 유죄를 주장하는 반드레퓌스파로 양분되어 격렬하게 투쟁했던 정치적인 스캔들로서, 국가권력에 의해 자행된 대표적인 인권유린, 간첩 조작사건을 말한다. 사회정의 실현과 진실규명을 위해 재심을 요구했던 드레퓌스파(재심요구파)는 진보, 좌파, 공화파, 사회주의자들이었고, 반드레퓌스파는 재심을 반대하였으며 국시, 군대의 명예, 국익을 위해서라면 판결이 번복될 수 없음을 주장했고 군부와 로마가톨릭교회, 왕당파들이 주류를 이루었다. 본 사건은 블랑제 사건, 파나마운하 스캔들과 함께 프랑스 제3공화국을 뒤흔든 3대 사건 중 가장 큰 위기를 겪게 만든 정치적 사건이라는 평가가 있다. 이 사건은 1894년에 참모본부에서 근무하던 드레퓌스 대위의 필체가 프랑스 정보요원이..."
