    "officialRecord": "잉글랜드 캔터베리 대주교 토마스 베켓이 캔터베리 대성당에서 암살되다.",
    "yasaStory": "1170년 12월 29일 사건: 잉글랜드 캔터베리 대주교 토마스 베켓이 캔터베리 대성당에서 암살되다.\n\n잉글랜드(영어: England)는 영국의 구성국 중 하나이다. 잉글랜드는 그레이트브리튼섬 남부의 대부분을 차지하며, 북쪽으로 스코틀랜드, 서쪽으로 웨일스와 아일랜드해, 남쪽으로 영국 해협, 동쪽으로 북해와 접한다. 지형은 대체로 평탄하며 면적은 130,395km2이다. 잉글랜드는 영국 전체 인구의 ⁠4/5⁠이상인 4,913만 8,831명(2001년 기준)을 보유하고 있으며, 잉글랜드에 위치한 런던은 영국의 수도다. 잉글랜드는 영국 역사에서 중심적인 역할을 했으며, 영국(英國)이라는 명칭은 별칭인 잉글랜드에서 유래했다. 잉글랜드 왕국의 독자적인 역사는 1707년 연합법으로 잉글랜드, 스코틀랜드, 웨일스가 그레이트브리튼 왕국으로 통합하면서 구성국이 되었다."
